quests[12822] = { id = 12822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know No Fear", description = "Now that we have the teleporter open, my plan is quite complex... it has several facets and will take impeccable coordination. And there are supplies to be gathered! And troops to recruit! Likely, weeks of hard labor as well!\n\nHahah, I had you going there for a moment, didn't I? You've got this, kid. Hop through the teleporter and take the fight to them! Our sappers will back you up... they won't have anywhere to run.", sourceObjective = "Ricket at K3 wants you to kill 6 Garm Watchers and 8 Snowblind Devotees.", progress = "Nothing strikes fear into the enemy quite like a goblin sapper!", completion = "Haha! That'll teach those brutes to waste our time. From this day forth, green skin will strike fear into the hearts of all magnataur!", sourceObjectiveStatus = "unverified-source-field" }
quests[12823] = { id = 12823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flawless Plan", description = "Hey there! Joining us for the assault I assume?\n\nI've got a special task for you... we're going to bring the whole cave down on their heads! Towards the back of their cave, you should find Frostgut's Altar.  Sneak up and plant this hardpacked explosive bundle somewhere close to it.\n\nOnce the charge is placed, stick around just long enough to make sure Frostgut bites it, then get out quickly! There's no knowing how long the cave will last once that thing goes off!", sourceObjective = "Gino at Garm's Rise wants you to plant the Hardpacked Explosive Bundle near Frostgut's Altar, kill Tormar Frostgut, and then escape the cave before it collapses on you.", progress = "That explosive bundle is my baby... it took me weeks to perfect it. WEEKS!\n\nThat's a long time... okay.", completion = "The whole mountain shook! Was it gorgeous? I bet it was! How could it not be?\n\nAnd the Inventor's League tells me all of my inventions just blow up. Darn right they do! Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[12824] = { id = 12824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolitionist Extraordinaire", description = "You've got some swift feet on you sonny! Thanks for lending a hand with those explosives... I've been waiting to give that invention a good test run for a while!\n\nGo ahead and tell Ricket we should be covered on the magnataur front now... my sappers will clean up any of the remaining baddies.\n\nThanks again!", sourceObjective = "Return to Ricket at K3.", completion = "You blew the whole place up? Way to go! I bet Gino got a kick out of that.\n\nWe really appreciate all of the help you've lent us, {name}. How 'bout a souvenir for your troubles?", sourceObjectiveStatus = "unverified-source-field" }
quests[12825] = { id = 12825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expressions of Gratitude", sourceObjective = "[PLACEHOLDER] Use mini-plane to kamakazi on the gnoll leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[12826] = { id = 12826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slightly Unstable", description = "Looking good!\n\nNo, not you - my new mines. You're just a little full of yourself, aren't you? I, on the other hand, am absolutely brilliant! My intellect cannot be matched.\n\nWhat were we talking about? Oh yes, my new mines! New and improved... ready for whatever devious use Ricket has concocted.\n\nBe a <good lad/doll> and go hand them off to Ricket, will you? She's right over there... it should be quite the epic journey, I'm sure. Be careful though, she's a little loopy.", sourceObjective = "Deliver Jeer's Improved Land Mines to Ricket in K3.", progress = "Jeer finished the mines? Dandy.", completion = "Well, aren't these just the cutest little packets of destruction you've ever seen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[12827] = { id = 12827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Rations", description = "Hey hey! You're a new face! Care to lend Ricket a hand?\n\nWe have a somewhat unexpected problem - food shortage. I know, I know... we should have seen that coming, but you don't get it. We tend to have somewhat of a quick turn-around here with our sapper squad and all, so usually we don't have to worry about long term eats. Good old K3's gotten popular though.\n\nConvenient solution? There are gnoll camps to the west and some gnolls scattered, scavenging as gnolls do. Care to go nab some of their rations?", sourceObjective = "Ricket at K3 wants you to repossess 16 Dried Gnoll Rations from the nearby Savage Hill Gnolls.", progress = "Hey there again! My belly's rumbling... how'd it go?", completion = "I hope they weren't too hesitant to share the wealth. We've been pretty forgiving with them picking through our leftovers thus far.", sourceObjectiveStatus = "unverified-source-field" }
quests[12828] = { id = 12828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ample Inspiration", description = "Wow! That stuff is nasty. Not to account for gnoll taste or anything, but I figured whatever they had would at least be... edible?\n\nLet's get more creative.\n\nTore's got an explosive dispenser north of town... not far from the big cavern entrance, can't miss it. I'm sure she intends them for mining purposes of some sort, but I've got a better idea.\n\nGrab one of those things and rush it to one of the nearby mammoths... most of them are to the west. Collect the meat, bring it back.", sourceObjective = "Ricket at K3 wants you to retrieve a U.D.E.D, use it to blow up a mammoth, and retrieve 8 Hearty Mammoth Meat.", progress = "I know my plan was brilliant. Don't even worry about it.\n\nDoes it feel good to be in the presence of greatness? A little tingly maybe?", completion = "And it's already well-done! I outdo myself sometimes.\n\nThanks much, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[12829] = { id = 12829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving In", description = "Hiya! The name's Tore. I  head up the mining operation here at K3... or I will shortly anyway!\n\nThis here cave is full of creepy-crawlies. I think we could do with a few less spiders before we move in - what'd you think?", sourceObjective = "Tore Rumblewrench outside of Crystalweb Cavern wants you to kill 12 Crystalweb Spiders.", completion = "Ha ha! Good to see you're up for some dirty work.\n\nMuch appreciated there, pal!", sourceObjectiveStatus = "unverified-source-field" }
quests[12830] = { id = 12830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ore Repossession", description = "We're moving in!\n\nThere were some snobolds here when we arrived... their mining operation seems to have met some unfortunate happenings though. Doesn't much matter - we were taking over soon anyway.\n\nI sent some of our miners in there to get me some ore samples that I can use to calibrate our machines for processing, but they haven't come back.\n\nMind going in there and nabbing some samples for me in their stead? The snobolds probably have some on them, though I'd expect most of them are dead by now.", sourceObjective = "Tore Rumblewrench outside of Crystalweb Cavern would like you to retrieve 5 samples of Impure Saronite Ore.", progress = "Ya have some ore for me?", completion = "Woo! That's a ripe stench right there! You had to get hands-on with some of those snobolds, didn't ya?\n\nI do appreciate it though!", sourceObjectiveStatus = "unverified-source-field" }
quests[12831] = { id = 12831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only Partly Forgotten", description = "Oi... it's like there's a propeller in my stomach.\n\nI think I can walk, but I got something nasty in my system when I got bit by something in the back of the cave. It was bigger than the other spiders... and brightly colored.\n\nRicket can probably make me an antidote, but she'd need the venom sac from whatever bit me. Would you mind finding it for me? I don't think Tore's coming.\n\nI'll just pretend I'm dead here and hopefully they'll leave me alone.", sourceObjective = "An Injured Goblin Miner in Crystalweb Cavern wants you to bring back an Icetip Venom Sac from an Icetip Crawler.", progress = "<The Injured Goblin Miner writhes in pain.>", completion = "That should cut it... I hope Ricket can put something together for me. Ready to get out of there, then?", sourceObjectiveStatus = "unverified-source-field" }
quests[12832] = { id = 12832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitter Departure", description = "Oi - thank you! I thought for sure I'd just be a spider snack. Perhaps I'm speaking a bit soon though - let's get the heck out of here!\n\nLet me know as soon as you're ready to go... make it quick.", sourceObjective = "Escort the Injured Goblin Miner out of Crystalweb Cavern and then speak to Ricket at K3.", completion = "Thanks for helping out our miner back there, {name}! I should be able to put together an antidote no problem.\n\nIf you stumble into Tore again, tell her that she's a jerk for me, will ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[12833] = { id = 12833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overstock", description = "Hey there again! You didn't run off like all the other adventurers did? Well, you're just a peach, aren't ya? I was beginning to think I smelled funny or something!\n\nWe could still use a bit of a hand around here, and you have just the right experience.  Remember those magnataur? Well apparently the cave didn't completely collapse... there are still quite a few left. So much for Gino taking care of them, eh?\n\nFortunately, Jeer made way more than enough mines. You've got this!", sourceObjective = "Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off the attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.", completion = "I like you. In fact, you rock!\n\nYay for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12834] = { id = 12834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Rain, Nor Snow, Nor Exploding Plane", sourceObjective = "[PLACEHOLDER] Test cold-weather bomber on giant.", sourceObjectiveStatus = "unverified-source-field" }
quests[12835] = { id = 12835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Grown Up", sourceObjective = "[PLACEHOLDER] Test Grown Up Jormungar on Giant", sourceObjectiveStatus = "unverified-source-field" }
quests[12836] = { id = 12836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expression of Gratitude", description = "I know just the job for an eager newcomer! We've got a gnoll problem. You might even call it a gnoll infestation! Pesky things. They keep creeping up more and more, and now they're on our doorstep, stealing our parts! Inconceivable.\n\nIt all begins and ends with their uppity leader, Gnarlhide. I want you to see to that \"ends\" part. Go pay him a visit at his camp all the way to the west, in Snowblind Hills.\n\nAnd when I say \"pay him a visit,\" that's a euphemism for \"kill him painfully.\" Kay? Kay!", sourceObjective = "Ricket at K3 wants you to kill Gnarlhide.", progress = "I like Ricket cause she's sooo delicious!\n\nOh, hey there again! How goes the pest control?", completion = "Groovy! You're my kind of {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12837] = { id = 12837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore's Got the Goods", sourceObjective = "[PLACEHOLDER] Report to Tore", sourceObjectiveStatus = "unverified-source-field" }
quests[12838] = { id = 12838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intelligence Gathering", description = "I need to know what the Scarlet Onslaught is planning today. You will be my instrument in this task.\n\nFly to Onslaught Harbor and rifle through their baggage trunks for documents. The trunks will be locked, so you'll have to take the keys from the Scarlet Onslaught members by whatever means.", sourceObjective = "Aurochs Grimbane at Death's Rise wants you to collect 5 Onslaught Intel Documents.", progress = "You have information for me?", completion = "Hand them over. I will sift through the useless ones and if there's anything actionable, I will call upon you.\n\nEither way, return tomorrow. It is well known that they change their plans on a daily basis.", sourceObjectiveStatus = "unverified-source-field" }
quests[12839] = { id = 12839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand (Admiral's) Plan", description = "At first this note looks like any of the other intel that you've been looking for. However, a quick perusal of its contents disabuses you of this notion.\n\nThe letter conveys that Grand Admiral Westwind is present somewhere on the island, but that he is keeping himself secluded for now. He speaks of a glorious day that is coming soon in which the Scarlet Onslaught will wash over first the Lich King and then the rest of world to finally bring order to Azeroth.\n\nThe lord-commander will want to see this!", sourceObjective = "Deliver the Note from the Grand Admiral to Lord-Commander Arete at Death's Rise.", progress = "Scarlet Onslaught intel is to be delivered to Aurochs Grimbane.\n\n<The lord-commander gives you an expectant look by way of a dismissal.>", completion = "A note written by Westwind? Why didn't you say so?\n\n<Arete tears the letter from your hand to read it.>\n\nThe fool! He's actually here?!\n\n<The lord-commander laughs.>\n\nThis is new information. I wonder how he imagines that he's going to conquer the world once he's taken down the Lich King? Not that he could accomplish either task in his wildest imaginings.", sourceObjectiveStatus = "unverified-source-field" }
quests[12840] = { id = 12840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Strict Confidence", description = "If anyone knows where the admiral is, then surely it must be his captains on the ships in Onslaught Harbor.\n\n<The lord-commander rubs his hands together.>\n\nWelsington and Hartford are their names if memory serves. Go beat the information out of them and then end their miserable lives.\n\nI want to know where the grand admiral is hidden!", sourceObjective = "Lord-Commander Arete at Death's Rise wants you to beat information out of Captains Welsington and Hartford.", completion = "They resurrected Landgren? He's the one that will know where the grand admiral is then!", sourceObjectiveStatus = "unverified-source-field" }
quests[12841] = { id = 12841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crone's Bargain", description = "Yes, it must be the little green prisoner you're after...  We might be able to help each other.\n\nYou're not going to get the goblin out of here by force. Not alive, anyway.\n\nAmong my people I am known as a Yrkvinn, a practitioner of illusions. As you can see, the Hyldnir have made me their prisoner.\n\nIf I had my runes, I could make you go unnoticed among them. Further inside, patrolling the mines, you'll find an overseer named Syra. She has my runes. Retrieve them and we'll talk some more.", sourceObjective = "Lok'lira the Crone inside the Forlorn Mine wants you to retrieve the Runes of the Yrkvinn from Overseer Syra.", progress = "My runes, {name}?  Do you have them?", completion = "I wasn't sure you were coming back.  I dread to think what will happen to me if I stay here for much longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12842] = { id = 12842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runeforging: Preparation For Battle", description = "The mark of war is etched indelibly upon your soul, death knight. You have learned the dark art of runeforging and with it you will engrave runes of power upon your weaponry.\n\nPreparations for battle must be made. Return to one of the runeforges, here in the Heart of Acherus, and use the power of runeforging to emblazon your weapon with a rune of power!\n\nReturn to me when your blade glows with dark energy!", sourceObjective = "Instructor Razuvious in Ebon Hold has commanded you to use your Runeforging ability to engrave a rune [of your choosing] upon your Runed Soulblade.\n\nYou may freely replace the engraving upon your weapon at any time, so long as you are near a Runeforge.", progress = "Do not waste time, {name}. We are on the brink of apocalypse!", completion = "Remember these words, {class}: The Runeforge is a Scourge instrument. It exists only in Acherus, Naxxramas and the heart of Icecrown! You may only emblazon your weaponry at a Runeforge.\n\nReturn often and emblazon all of your weapons. A {class} must be prepared for all that would dare oppose him!", sourceObjectiveStatus = "unverified-source-field" }
quests[12843] = { id = 12843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Took Our Men!", description = "You have to help us!  We were in the middle of an expedition into the mountains to set up a transmission tower when we were attacked.\n\nThey looked like vrykul, except their skin was blue and layered with frost... and they were all female!  They took all the men in the expedition and let us women go.  Please, {name}!  We think they're being held in Sifreldar, the village overlooking K3.", sourceObjective = "Gretchen Fizzlespark wants you to go to Sifreldar Village and rescue 5 Goblin Prisoners.", progress = "Did you find our men, {name}?", completion = "You did it!  Our boys are back!", sourceObjectiveStatus = "unverified-source-field" }
quests[12844] = { id = 12844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipment Recovery", description = "Please, {name}.  When the Hyldnir took our men, they also took all our equipment.  Of course, it's more important that we get our boys back, but if you run into any of our equipment, I'd really appreciate it if you brought it back to us.\n\nYou'll find their village just above us, to the north.", sourceObjective = "Gretchen Fizzlespark wants you to obtain 8 pieces of K3 Equipment in Sifreldar Village north of K3.", progress = "Any luck with our equipment, {name}?", completion = "Thanks, {name}!  We'll see what we can do to salvage these parts!", sourceObjectiveStatus = "unverified-source-field" }
quests[12846] = { id = 12846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Goblin Behind", description = "All of our boys are back... thanks to you, {name}!  Well... all but one.\n\nMy brother Zeev is still up there according to the others.  Apparently they have some sort of mine where they make their prisoners work.  Go in there and see if you can find out anything.", sourceObjective = "Find the entrance to the Forlorn Mine in northern Sifreldar Village and look for clues for Zeev Fizzlespark's whereabouts.", completion = "You're definitely not with the Hyldnir... so what are you here for?  Ah... you must be looking for the new prisoner!", sourceObjectiveStatus = "unverified-source-field" }
quests[12847] = { id = 12847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Chances", description = "I'd heard they have an archbishop in their cathedral, but I had no idea that they'd resurrected and promoted Landgren! The Crimson Cathedral is heavily guarded with only one entrance, so you'll need help.\n\nWe still need to know where the grand admiral is, but this time we're not taking any chances!\n\nTake this device. It can be used to summon a gate for me to step through once you've killed the archbishop.\n\nI'll have my answers directly from his compelled soul! We will find Grand Admiral Westwind!", sourceObjective = "Kill Archbishop Landgren and then summon Arete's Gate in the presence of his corpse. Speak with Lord-Commander Arete inside The Crimson Cathedral once he's completed his questioning of the archbishop's spirit.", progress = "Yes?", completion = "Hidden caves on the backside of the island. How very interesting.\n\nWell, at least now I know where all of my missing spies are.", sourceObjectiveStatus = "unverified-source-field" }
quests[12848] = { id = 12848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Hunger", description = "The endless hunger will soon take hold of you, {class}. When it does, you will feel pain immeasurable. There is only one remedy for the suffering: the hunger must be sated.\n\nI give you the key to your salvation.\n\nChained to the Heart of Acherus are those deemed unworthy of the dark brotherhood. Use the key to free an unworthy initiate. Allow them to equip their gear and battle you for their freedom. Kill and the pain will cease. Fail and suffer for eternity.\n\nLive or die - the choice is yours to make.", sourceObjective = "Instructor Razuvious in Ebon Hold has commanded you to free an Unworthy Initiate and then kill the Unworthy Initiate in cold blood!\n\nIt's your life or theirs!", progress = "Two lives, one key... Do not fail me, {name}.", completion = "As expected, my chosen knight has triumphed! You are ready, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12849] = { id = 12849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power Of Blood, Frost And Unholy", sourceObjective = "Within the Hall of Command you will find the schools of blood, frost and unholy. Each school has a trainer that can provide you with knowledge in the various dark arts.\n\nI, Lord Thorval, am the headmaster of the school of blood. Lady Alistra reigns over unholy and the arch-lich, Amal'thazad, holds dominion over frost.\n\nYou must return here whenever you gain power and train!", sourceObjectiveStatus = "unverified-source-field" }
quests[12850] = { id = 12850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report To Scourge Commander Thalanor", description = "Scourge Commander Thalanor awaits your arrival at the overhang located directly southeast of our current position. Report to Thalanor and requisition a Scourge gryphon to deliver you to Death's Breach.\n\nPrince Valanar will be waiting for you down below.\n\nSuffer well, <brother/sister>!", sourceObjective = "Report to Scourge Commander Thalanor at the balcony on the first floor of Ebon Hold.", completion = "The war has begun, {class}! I shall place you upon my finest gryphon and deliver you to Death's Breach. Chaos, death, destruction! You will herald in all of this and more!", sourceObjectiveStatus = "unverified-source-field" }
quests[12851] = { id = 12851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearly Hanging On", description = "The test awaits, woman!\n\nDo you have the heart of a warrior queen? Or that of a sniveling seamstress?\n\nOne taste of war and you'll know the answer.\n\nYou might lie to your mother, your sisters, and even yourself, but the battlefield always exposes one's true nature.\n\nWhen you've made your preparations, mount Icefang and ride into battle. From her back, you must rain down a shower of death upon our enemy.", sourceObjective = "Brijana at Brunnhildar Village wants you to mount Icefang and shoot 7 Frostworgs and 15 Frost Giants in the Valley of Ancient Winters.", progress = "Have you survived the battle, {name}?", completion = "Perhaps you do have the heart of a warrior.\n\nTime will tell...", sourceObjectiveStatus = "unverified-source-field" }
quests[12852] = { id = 12852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral Revealed", description = "When High General Abbendis was confronted at New Hearthglen, the grand admiral protected himself within an impenetrable sphere of magic before making his escape.\n\nI am particularly adept at nullifying magic.\n\nTake this to use against him inside The Hidden Hollow when he puts the sphere up. I wish that I could be there to see the look on his face when you do it.\n\nDeal with him.", sourceObjective = "Lord-Commander Arete wants you to deal with Grand Admiral Westwind. Return to the lord-commander upon Death's Rise after you have done so.", completion = "MAL'GANIS?!!\n\n<The lord-commander laughs with abandon.>\n\nThe fools were taken in by the demons yet again and now they are destroyed!\n\nI trust that my favorite {class} will stick around long enough to help us finish off the rest of them? Perhaps one of these would convince you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12853] = { id = 12853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luxurious Getaway!", description = "Hey there, pal!\n\nDo you like excitement and explosions?! Who doesn't? I know just the place for you. Down at luxurious K3, they're always making innovative inventions and finding all-new ways to make things blow up! Sounds thrilling, doesn't it? If you want to be part of the fun, head on down today and speak to Jeer Sparksocket!\n\nMandatory disclaimer: manual labor may be required to partake in previously indicated \"excitement.\"", sourceObjective = "Speak to Jeer Sparksocket at K3 in the Storm Peaks.", completion = "Welcome to K3!\n\nWe came here to make our way into those peaks and get our fair share of some of those amazing titan machines. Progress on that end has been somewhat minimal, though. Gnolls, snobolds, magnataur... there's no shortage of trouble to go around... not to mention, we can't seem to keep any fliers in the air without their motors freezing.\n\nThere's plenty of work to be done though - lend a hand, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[12854] = { id = 12854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Brann's Trail", description = "After the discovery of Brann's journal in Grizzly Hills, we've only had one other communication from Brann. A mysterious note found its way to Explorers' League headquarters in Ironforge, with no indication of where it came from. All it said was that we're to meet Brann at his camp and help him with his search.\n\nFrom what I can tell, the camp should be located northeast of here, across the Bor's Breath River and at the foot of some ruins from the Path of the Titans.", sourceObjective = "Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Archaeologist Andorin at Frosthold.", progress = "Did you find Brann's camp?", completion = "<Archaeologist Andorin looks at you expectantly.>\n\nYou were supposed to come back with Brann, not a piece of paper. What's going on here?", sourceObjectiveStatus = "unverified-source-field" }
quests[12855] = { id = 12855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Out the Perpetrator", description = "The tone of Brann's note suggests he meant to bury something with the note, maybe a pack of some kind. You're sure this was all you found?\n\nOkay, I'm going to have you take one of these frosthounds with you. The frostborn use them for tracking. Bring it to the destroyed camp and let it get Brann's scent.\n\nIt should at least lead you to the location of those missing possessions, and if we're lucky, Brann himself.", sourceObjective = "Use the Frosthound Collar at the Abandoned Camp to track down whoever took Brann's possessions. When you recover them, use the communication device and speak to whoever you can contact.", progress = "Who are you?", completion = "You... you're not a member of the Explorers' League, at least not one I remember. But, if you recovered the communicator, they must've sent you. Good, that's almost what I was hoping for.", sourceObjectiveStatus = "unverified-source-field" }
quests[12856] = { id = 12856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Hearted", description = "To be slain honorably on the field of battle brings us all glory. To be frozen in a block of ice and endlessly taunted does not....\n\nYou are to fly to the frost giant city of Dun Niffelem, just east of the Valley of Ancient Winters, and liberate a captive proto-drake. With her, you will be able to free our sisters from their frozen bonds and carry three of them safely home.\n\nBeware the giants' clubs, sister, lest you find yourself numbered among the captives.", sourceObjective = "Brijana, just east of Brunnhildar Village, wants you to fly to Dun Niffelem, then free 3 Captured Proto-Drakes and rescue 9 Brunnhildar Prisoners.", progress = "Was your mission successful, sister?", completion = "Your efforts appear to have been successful, sister.\n\nYou have brought glory to the Brunnhildar!", sourceObjectiveStatus = "unverified-source-field" }
quests[12857] = { id = 12857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Ragemane's Flipper", description = "Posted by Chief Rageclaw:\n\nChief Rageclaw trusty lion seal, Ragemane, bite hand that feed him. Rageclaw say Ragemane no more good because of bad Drakuru trolls. Chief Rageclaw very sad to ask that Ragemane be killeded and Ragemane flipper be returned to chief as proof.\n\nYou find Ragemane to southeast, at Rageclaw Lake.\n\nChief Rageclaw sorry for bad writing. First time use one of these things; plus, Chief Rageclaw is wolvar, not person.", sourceObjective = "Recover Ragemane's Flipper and return it to Chief Rageclaw at Light's Breach in Zul'Drak.", progress = "Poor Ragemane. He was gift from brother-in-law.", completion = "<Chief Rageclaw cries.>\n\nHad Ragemane since pup. Sad day for Rageclaw. First troll attack Rageclaw, then troll make Ragemane bad. Rageclaw never trade with troll again!", sourceObjectiveStatus = "unverified-source-field" }
quests[12858] = { id = 12858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces to the Puzzle", description = "Thank the Light that someone got my message. Now that I'm safe from the iron dwarves, I need to ask your help with something. I've got a lead on Norgannon's keystone, which guards access to Ulduar's archives, but the Titans divided it into two pieces and secreted them away.\n\nOne of the pieces, the keystone's shell, is held within the Inventor's Library on the northern coast, south of Ulduar itself. The first thing you'll need to do is retrieve the fragments of an access disk from the library's guardians.", sourceObjective = "Gather 6 Inventor's Disk Fragments and use them to assemble the Inventor's Disk.", progress = "Did you complete the disk?", completion = "Wonderful! Now that we have the disk, you must use it to open the Inventor's vault!", sourceObjectiveStatus = "unverified-source-field" }
quests[12859] = { id = 12859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Just In: Fire Still Hot!", description = "Trolls attack Rageclaw Den and kick Rageclaw out! It get worse. Trolls now burning village! This very bad. Chief make top Rageclaw shaman, Moky, do study on fire. Results very surprising! Fire still hot and can burn things.\n\nWill you help Rageclaw and put fire out? Moky has special Rageclaw fire extinguisher for you. Use special fire extinguisher to put out fire at Rageclaw Den to southeast. Sometimes take many sprays to douse fire, but extinguisher always have water! Rageclaw magic strong!", sourceObjective = "Elder Shaman Moky at Light's Breach in Zul'Drak wants you to use the Rageclaw Fire Extinguisher to douse 15 hut fires at Rageclaw Den.", completion = "It strange because I know you put fire out, but fire still burning. Maybe this thing not so good after all, eh? Still, Moky pay you for what you do! Hopefully troll burn too!", sourceObjectiveStatus = "unverified-source-field" }
quests[12860] = { id = 12860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Mining", description = "That disk you assembled... it's blank! That crafty Mimir must've hidden the information somewhere else. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be what you need to do with the disk. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", sourceObjective = "Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks.", progress = "Did you try using the disk? What did you find?", completion = "<Brann looks at the disk as you hold it up.>\n\nI can't tell if there's anything stored there or not! You have to tell me what happened.\n\n<You describe the data retrieval process.>\n\nSo it worked? At least we can count on Mimir to be systematic. Can't say that for the rest of these Keepers from what I've been hearing...", sourceObjectiveStatus = "unverified-source-field" }
quests[12861] = { id = 12861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls Is Gone Crazy!", description = "Drakuru... You know who this troll is? I think bad troll are controlled by the Drakuru troll. They call themself Drakuru trolls - that how I know. Now you see why I am chief of Rageclaw. Smartest of all wolvar!\n\nBut that not why I talk to you now. Bad troll come and kick Rageclaw out of den. Rageclaw that no run away held as prisoner in village. You go to Rageclaw Den, southeast, and free captured Rageclaw. Kill troll for lock opener. You maybe kill many troll for many lock opener.", sourceObjective = "Chief Rageclaw at Light's Breach in Zul'Drak wants you to use the Drakuru \"Lock Openers\" found on various Drakuru trolls to free 8 Captured Rageclaw.", completion = "Rageclaw thank you, {name}. Though Rageclaw Den probably lost forever and troll-Rageclaw friendship also lost forever... and also now I think of it, Ragemane lost forever too. Also brother-in-law. He gone. Hrm, have you seen Chief's mate? I think she gone too.\n\nMaybe you go now. Chief a little depressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[12862] = { id = 12862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", sourceObjective = "Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks.", completion = "Ow! That looked painful. It was a pretty grand entrance though, lad!\n\nWelcome to Frosthold! Are ya here to help us find a path into Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[12863] = { id = 12863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offering Thanks", description = "Ah! Thanks for coming up here, <lad/lass>.\n\nJudging by your wide eyes and shivering hands, I'd venture a guess that you're somewhat new. Sounds like it would be good for you to meet our gracious hosts then!\n\nWe've got some extra medical supplies... to be honest, we weren't expecting to have such a comfortable setup. Go ahead and give this crate to Glorthal over there, and lend them a hand if you would too. We don't want them to think we're ungrateful for how welcoming they've been.", sourceObjective = "Bring the crate of medical supplies to Glorthal Stiffbeard in Frosthold.", progress = "Hello.", completion = "Medical supplies? Thank you! Not exactly sure what to do with them to be honest, but I'm sure they'll be useful.\n\nIt's good to meet you... there's such a colorful variety among your peoples. We're not used to having visitors up this way very often - it's good to have some fresh company.", sourceObjectiveStatus = "unverified-source-field" }
quests[12864] = { id = 12864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Scouts", description = "There is something that I could use a hand with now that I have you.\n\nWe have a few scouts that are extremely late in returning. The peaks are harsh... but these boys know what they're doing.\n\nHead to the east... along the Bor's Breath valley and near Bor's Fall... they should be out that direction. If you find any sign of one of them, bring me back news immediately. We have a few enemies in the area - if any of them are getting a bit uppity, the more warning the better.", sourceObjective = "Glorthal in Frosthold has requested a search of the Bor's Breath valley and Bor's Fall for any sign of the missing Frostborn Scouts.", completion = "When a scout doesn't come back for this long... that's about the expected result. The harpies then?\n\nKing Stormheart has us train hard year round... he's turned us into amazing fighters. At times like this, I understand why it's necessary. He's the wisest and strongest leader I've yet seen among our people... don't let his peachy skin fool ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[12865] = { id = 12865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyal Companions", description = "Fresh blood! Good to meet ya! I've got some work if you've got some time.\n\nOff to the east are the Foot Steppes... pretty hard land, but there's quite a group of rhino that graze there. Our birds have a taste for that rhino meat, but it's always a bit dangerous for them to go hunting with all of the proto-drakes that nest around there.\n\nIf you're keen, head over that way and get some rhino meat, bring it back to the peaks above here, and then use it to feed some of the eagles that nest there.", sourceObjective = "Fjorlin Frostbrow at Frosthold wants you to obtain 8 slabs of Fresh Ice Rhino Meat and use them to feed the Stormcrest Eagles above town.", progress = "These birds have been loyal to us for a long time... we get on pretty well.", completion = "Thank you, kindly... and I'm sure they're quite appreciative too. They make powerful allies; you'll be well off being on this side of their graces.", sourceObjectiveStatus = "unverified-source-field" }
quests[12866] = { id = 12866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stemming the Aggressors", description = "Damn harpies. We've beat that bunch into submission more times than I can remember... and they stay quiet for a time after each bout. This time, I'd thought that maybe it sunk in.\n\nApparently not.\n\nTheir memory may be a bit short, but if their numbers are thinned enough, they'll keep to themselves. Head into the valleys in the north and east and clear out a fair chunk of them for me, will ya?", sourceObjective = "Glorthal Stiffbeard at Frosthold wants you to kill 8 Frostfeather Screechers and 8 Frostfeather Witches.", completion = "It's dirty work, I know, but we appreciate it. Now what was the name the scout mentioned... Sirana?", sourceObjectiveStatus = "unverified-source-field" }
quests[12867] = { id = 12867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby Stealers", description = "A few weeks ago, if you looked up, you'd see dozens of those beautiful eagles soaring the skies. Now, only a few if any. They've taken to staying with their nests nearly all the time now because the harpies have been stealing their eggs.\n\nThe harpies have grown a taste for eagle flesh, it seems... the sick wretches are caring for the eggs long enough to feast on the hatchlings. Go into the valleys to the north or the east and find the eggs... bring them back here, and I'll take them back to the nests.", sourceObjective = "Fjorlin Frostbrow at Frosthold would like you to bring back 15 Stormcrest Eagle Eggs.", progress = "We'll get this harpy problem taken care of... the eagles will be free to soar the skies again soon.", completion = "Good stuff, lad. You're making fast friends.\n\nIf you stop back by soon, I'm sure we can find one that will let you ride... they should know that you're trustworthy now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12868] = { id = 12868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirana Iceshriek", description = "This Sirana Iceshriek sounds like the one that's spurring the harpies to be more aggressive. If we kill her, I suspect their attacks won't last long afterwards.\n\nOne of our stormriders claims to have spotted her circling the peak directly northwest of here.  Go find the wench and put her down. Let's see this done.", sourceObjective = "Glorthal Stiffbeard at Frosthold wants you to kill Sirana Iceshriek.", completion = "It's done then. Thank you.\n\nI've spoken with Fjorlin - he said that his men will take charge of keeping the harpies down a bit. As long as we don't let up again, they won't find the courage to think they can attack our people.\n\nI know this wasn't the most tasteful work - take this as a token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[12869] = { id = 12869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushed Too Far", description = "You were there with Loken, weren't you? The iron dwarves captured Veranus, the brood mother of the proto-drakes. The drakes don't seem even a little bit happy about the situation... they've gotten very aggressive.\n\nThey've pushed into stormcrest territory and the eagles have taken to an all out fight with them. It's time to return the favor. We're riding to the Foot Steppes and slaughtering them there.\n\nKing Stormheart left this hammer to me - make good use and see to it that I get it back.", sourceObjective = "Fjorlin Frostbrow at Frosthold wants you to ride with a Stormcrest Eagle and kill 16 Stormpeak Wyrms in the Foot Steppes.", progress = "This is completely out of control.", completion = "I don't see the drakes being dissuaded so easily. Stop back by tomorrow if you think you can spare more time to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[12870] = { id = 12870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Relics", description = "Why hello thar!\n\nBefore you be headin' off to do your grand questin' and adventure, might I beg a wee favor of ya, <lad/lass>?\n\nThese mountains be packed full'a precious relics and baubles... this place be a dream come true for tha league. I'd be much obliged if ya could bring any such treasures you stumble upon back ta me. You can even share in me ale for tha trouble! Trust me <lad/lass>, that's a rich deal!", sourceObjective = "Return 10 Relics of Ulduar to Rork Sharpchin in Frosthold.", progress = "Did ya find some o' dem relics for me?", completion = "Beaut! Yer a good one you are.\n\nTilt one back wi' me! Let us celebrae' this glorious find!", sourceObjectiveStatus = "unverified-source-field" }
quests[12871] = { id = 12871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid from the Explorers' League", description = "Interesting. I don't see any locking mechanisms on the shell. That suggests to me that it may take more than just finding the other piece to combine the keystone.\n\nTake the shell back to the expedition leader, Lagnus, at Frosthold. Once he gets over his awe, he should be able to glean what the core looks like based on the shell, and maybe they can get the Frost Dwarves to help find it.\n\nI'm going to see if I can find out how to combine the two pieces. We'll catch up once we've both made some progress.", sourceObjective = "Take Norgannon's Shell to Lagnus at Frosthold.", progress = "Hello there!", completion = "By Muradin's beard! Is that what I think it is?! Brann's really outdone himself this time... and you too for that matter! The boys back home are never going to believe this.", sourceObjectiveStatus = "unverified-source-field" }
quests[12872] = { id = 12872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", sourceObjective = "Recover Norgannon's Shell from Archivist Mechaton.", progress = "Well, don't just stand there, show me the shell!", completion = "That's it! That's the first half of Norgannon's keystone. Well done, {name}. When I get back to Ironforge, I'm going to have you inducted as an honorary member in the Explorers' League!", sourceObjectiveStatus = "unverified-source-field" }
quests[12873] = { id = 12873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frostborn King", description = "Definitely... I can see exactly what the core must look like. If any of the frostborn have seen it, they'll be sure to recognize the description.\n\nThere's no time to waste, let's get straight to business. Go talk to King Stormheart and request his aid... he's sure to know someone who can help us find the core. And be nice about it will you - he's very respected around here.", sourceObjective = "Speak to Yorg Stormheart in Frosthold.", completion = "Norgannon's Core? Never heard of it. I might well know someone that has though.", sourceObjectiveStatus = "unverified-source-field" }
quests[12874] = { id = 12874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fervor of the Frostborn", description = "I be more than willing ta lend my shelter and home ta travelers in need, but I'm nae too keen ta force my people inte yer affairs.\n\nI'll tell ye what... my people are warriors, straight and true. On the day a frostborn becomes a man, he has ta prove himself in battle. He has ta show us that he'll not let size hold'm back.\n\nShow me yer as strong and fierce as one of my men, and I'll have them lend ye an ear or a blade. Speak ta Fjorlin over by the cliff to the south there and he'll put ye ta the test.", sourceObjective = "Yorg Stormheart at Frosthold has requested that you speak to Fjorlin Frostbrow to secure a ride and face your challenge.", progress = "Ye've come back to me. Have ye come back to me victorious?", completion = "Ha! Grand tale lad... perhaps ye have a bit of frostborn blood in ye, eh? Yer not just talk anyway, and that's what I needed to hear.", sourceObjectiveStatus = "unverified-source-field" }
quests[12875] = { id = 12875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Experienced Guide", description = "I don't know where this core is hiding, but ye knew that. I said I'd help though, and that I shall.\n\nThere's a hermit by the name of Drom Frostgrip who lives in a cave north of here... down in tha valley. We've strayed away from the titans a bit ourselves being that there are so few about, but Drom's loyal to the old ways... he keeps an eye on their most precious places and speaks te the keeper Creteus often.\n\nYer sure to find him in the back of his cave... tell'm I sent ye and he'll help ye.", sourceObjective = "Locate Drom Frostgrip.", completion = "<Drom coughs up a bit of blood.>\n\nNorgannon's Core, eh? I've spent a fair number of days trying to find anything I could about it myself, but it seems to be one of the relics that's still guarded. With reason I suppose.\n\nIf King Stormheart sent you, he surely must see something noble in ye... and I'm not one to refuse my king.", sourceObjectiveStatus = "unverified-source-field" }
quests[12876] = { id = 12876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Guests", description = "Our scouts have spotted iron dwarves in the valley north of here. I overheard King Stormheart sending you to visit Drom and I'm admittedly a bit worried about'm.\n\nIf you find any iron dwarves when you head down there, put'm down hard and fast for me, eh? I dun think they know exactly where we are or how to get here just yet, and I'd prefer to keep it that way.", sourceObjective = "Fjorlin Frostbrow at Frosthold wants you to kill 10 Stormforged Invaders.", progress = "Were the scouts right? Were there dwarves down there?", completion = "Grim news, lad. Those iron dwarves seem to be increasing in numbers... we've been seeing them all over the mountains. I smell war coming.\n\nThank you for dealing with this bunch... a little more time bought.", sourceObjectiveStatus = "unverified-source-field" }
quests[12877] = { id = 12877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lonesome Watcher", description = "I never found the core... but I've often spoken to the keeper Creteus, and his omissions give him away. You'll find Creteus over the mountains to the east, in the Foot Steppes, keeping watch on the Engine of the Makers. The core might well be in there, but you'll need to win Creteus's favor.\n\nThe iron dwarves were here looking for something... it might well be the core. They took my ring. Find their leader, get the ring back, and show it to Creteus so that he knows I sent you.", sourceObjective = "Recover Frostgrip's Signet Ring from an Iron Dwarf Monitor and then bring it to Creteus in the Foot Steppes.", progress = "Hello, {race}.\n\nI am pleased that you have opted to utilize your tongue over your blade when making my acquaintance. I have found that a more and more rare quality among your kind of late.", completion = "Drom's ring? I am to assume Drom is not well if he did not introduce you directly. I am sorry to hear of that. Drom is a noble dwarf, if an inquisitive one.\n\nOn what business have you come then?", sourceObjectiveStatus = "unverified-source-field" }
quests[12878] = { id = 12878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Relic", description = "During your absence, I was privileged enough to parley with the dwarf Brann Bronzebeard. This dwarf indicated his purpose for seeking the keystone, and I am satisfied that it is for satisfactory intent... I believe this dwarf may be the entity for which the keystone was created.\n\nNorgannon's Core is located in the Frigid Tomb to the southeast. Its guardians are ancient beings of ice, and they will not welcome your presence. Best these guardians and retrieve the keystone with my blessing, {race}.", sourceObjective = "Creteus in the Foot Steppes has provided you with the information to locate Norgannon's Core.", completion = "<As the chest opens, air rushes out into the chamber, carrying with it the musty smell of something that has been here for countless years. Norgannon's Core rests in the bottom of the chest, undisturbed by the ages.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12879] = { id = 12879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Frostborn King", description = "<As you retrieve the core from the chest, you hear the thumping of heavy footsteps rushing towards you from the corridor. There is the faint sound of battle in the distance.>", sourceObjective = "Bring Norgannon's Core back to Creteus in the Foot Steppes.", progress = "Someone is using the Forge of Wills to create this army... Ulduar is no longer safe. {race}, did you recover the core?", completion = "Someone is using the Forge of Wills to create this army... Ulduar is no longer safe.\n\n{race}, I am pleased that you were able to reach the core before these abominations were.", sourceObjectiveStatus = "unverified-source-field" }
quests[12880] = { id = 12880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Explorer", description = "Combining the keystone will require Norgannon's Binding - a device located in the Engine of the Makers, the large pit beside us. Brann should be down there with the other half of the keystone now. I have instructed him on the use of the device. He awaits your presence.\n\nI will do what I can to keep the iron dwarves occupied, but I do not have confidence that I will hold them for long. King Stormheart is returning to the defense of Frosthold with some of his men shortly. Please hurry, {race}.", sourceObjective = "Bring Norgannon's Core to Brann Bronzebeard in the Engine of the Makers.", progress = "Hey there, lad! Good to meet ya in person. Did you find it?", completion = "You're brilliant, lad! Brilliant! This will be a glorious day indeed.\n\nQuickly, hand me the core before those iron dwarves make their way down here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12881] = { id = 12881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard" }
quests[12882] = { id = 12882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Relics", description = "Welcome to the peaks.\n\nI have a simple request before you head off on whatever grand jaunt you have planned. There are relics and treasures of ancient Ulduar scattered through these mountains. Most are likely in possession of the various sentient races.\n\nReturn any that you find to me, and I will reward you in kind. Perhaps I'll even let you partake on my many potent ales.", sourceObjective = "Return 10 Relics of Ulduar to Olut Alegut at the Grom'arsh Crash-site.", progress = "Were you able to find the relics of which I spoke?", completion = "These will do nicely! I am much obliged. Perhaps a drink for your troubles?", sourceObjectiveStatus = "unverified-source-field" }
quests[12883] = { id = 12883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders From Drakuru", description = "Minions be hearin' da call of your masta! Da Lich King be givin' Drakuru full control of da armies of da Scourge in Zul'Drak. We be commanded ta kill everyting.\n\nEVERYTING MUST DIE!\n\nWe be processin' all da corpses in da Dead Fields and sendin' em up ta Prince Navarius' crew in  Zeramas for Scourgin'! Notin' goes ta waste on Drakuru's watch!\n\nSoon we be drinkin' da blood of da prophets ta become stronger dan eva before! Zul'Drak and Gundrak gonna fall to da Scourge!", sourceObjective = "Return the Orders From Drakuru to Crusader Lord Lantinga at Light's Breach in Zul'Drak.", progress = "Drakuru, eh? I've heard the name before...", completion = "If this is the same Drakuru from Drak'Tharon Keep we are going to need... outside assistance.\n\nDeath knights of Acherus are stationed nearby, undoubtedly following the same trail of Scourge destruction that lead the Argent Crusade here. As half of our army is tied up at the Argent Stand, battling crazed Drakkari trolls, we will have to join forces with the Knights of the Ebon Blade.\n\n<Lantinga mutters under his breath.>\n\nI was hoping I'd never have to see those scoundrels again after Light's Hope...", sourceObjectiveStatus = "unverified-source-field" }
quests[12884] = { id = 12884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ebon Watch", description = "West of here, across the ruined roads and structures, is the death knight encampment of Ebon Watch.\n\n<Crusader Lord Lantinga rolls up Drakuru's orders.>\n\nTake these orders and deliver them to Stefan Vadu. He is the death knight in command at Ebon Watch. Let him know that the Argent Crusade will deal with Prince Navarius. They'll have to handle Drakuru.\n\nBe careful, {name}. The way to Ebon Watch is teeming with Scourge.", sourceObjective = "Deliver the Orders From Drakuru to Stefan Vadu at Ebon Watch in Zul'Drak.", progress = "What have you got there, {race}?", completion = "<Stefan reads the missive, then crumples it up and tosses it into the fire.>\n\nOld news. The Argent Crusade is - once again - late to the party. We've been tracking Drakuru since Grizzly Hills. He is slated for eradication.", sourceObjectiveStatus = "unverified-source-field" }
quests[12885] = { id = 12885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exiles of Ulduar", description = "The Storm Peaks are an intriguing place, but there's far more here than titan ruins. The peoples who live here face a dire threat in Loken and his minions.\n\nHe sent his favorite servants, the iron dwarves, on a brutal campaign against all the creatures of stone. He expelled the earthen from Ulduar, forcing them to take shelter at Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren are beset by the iron dwarves there. Find and help them, {name}.", sourceObjective = "Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "So you know Brann Bronzebeard, then? He is our closest ally among those of the flesh. We are as brothers in the struggle against Loken and his followers, in the struggle for Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12886] = { id = 12886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drakkensryd", description = "This is it.  You've passed all the tests of the Hyldsmeet... all but one.  You've risen among our sisters' best and fiercest.\n\nThe final test is at hand.  The Drakkensryd - the true test of a Hyldnir's worth and warrior spirit.  It'll be you, your riding drake, a chained harpoon and a score of your sisters vying for dominance.\n\nShow no quarter.  None will be expected.", sourceObjective = "Use the Hyldnir Harpoon to defeat 10 Hyldsmeet Drakeriders at the Temple of Storms. Use the Hyldnir Harpoon on a Column Ornament to exit the Drakkensryd and speak to Thorim when you've succeeded.", progress = "Begone!", completion = "Sif... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12887] = { id = 12887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur dwarves have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", sourceObjective = "Destroy The Ocular and then report to Baron Sliver at The Shadow Vault.", progress = "The Ocular still stands! Thassarian was a fool to trust you.\n\nWhoever you are, don't return again until it is destroyed. My position here must not be compromised!", completion = "Perhaps now we can really get something done. Don't be fooled though, the Lich King can still 'see' through his Scourge minions.\n\nThat's why you're here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12888] = { id = 12888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SCRAP-E", description = "This card allows the user to access the control panel of the scrapbot designated SCRAP-E, in order to perform maintenance and reprogram the bot's directives.\n\nSCRAP-E appears to be assigned to the interior of the building at The Inventor's Library. The card displays a list of the bot's broken components and failing systems. With the proper parts, the bot can be restored to working condition.", sourceObjective = "Bring the SCRAP-E Access Card along with 4 Handfuls of Cobalt Bolts and 5 Overcharged Capacitors to SCRAP-E at The Inventor's Library.", progress = "<You open SCRAP-E's access panel.>", completion = "<You begin performing the repairs indicated by the access card. When the repairs are complete, you close the access panel and throw the power switch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12889] = { id = 12889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prototype Console", description = "Designation SCRAP-E.\n\nDirective: Maintain consoles and databases of Inventor's Library in Keeper Mimir's absences.\n\nTime since last maintenance cycle: 489 days.\n\nStatus of schematic data: unknown.\n\nCurrent tasks: Repair prototype console.", sourceObjective = "Interact with the Prototype Console in The Inventor's Library.", completion = "You examine the display on the repaired prototype console. At least one of Mimir's schematics seems to have survived the long period between maintenance cycles. From the diagrams and instructions displayed in the schematic's file, you could easily construct the mechagnome shown.", sourceObjectiveStatus = "unverified-source-field" }
quests[12890] = { id = 12890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Size Mattered..." }
quests[12891] = { id = 12891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Have an Idea, But First...", description = "When I was in the - ahem - employ of the Lich King, we would often use a device known as a sovereign rod to keep some of the more intelligent Scourge in line.\n\nI require that you assist me in the construction of a new one.\n\nLuckily for you, all of the necessary components are at hand: a cultist rod, an abomination hook, a geist rope, and a handful of Scourge essences.\n\nThis should not be difficult, {class}.", sourceObjective = "Baron Sliver at The Shadow Vault has asked you to collect a Cultist Rod, an Abomination Hook, a Geist Rope, and 5 Scourge Essences.", progress = "When you've managed to acquire that which I have asked of you, I will fashion the device, with a few modifications for our purposes, and we'll be on with our business.", completion = "Quickly, hand them to me and stay out of sight!\n\nThe rod, the hook, and the rope are all very self-evident in their usage when combined. I just need to infuse the result with the essences and we'll be ready to proceed.\n\nIt's all very mundane in its composition, but extraordinary in its application!", sourceObjectiveStatus = "unverified-source-field" }
quests[12892] = { id = 12892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur goblins have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", sourceObjective = "Destroy The Ocular and then report to Baron Sliver at The Shadow Vault.", progress = "The Ocular still stands! Koltira was a fool to trust you.\n\nWhoever you are, don't return again until it is destroyed. My position here must not be compromised!", completion = "Perhaps now we can really get something done. Don't be fooled though, the Lich King can still 'see' through his Scourge minions.\n\nThat's why you're here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12893] = { id = 12893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Your Mind", description = "Vile, Lady Nightswood, and The Leaper would make excellent weapons in the fight against the Lich King if they can be broken from his will. That is what the Sovereign Rod is for.\n\nYou'll find them on the ledges to the east and west of the vault, as well as on the mid-tier of the vault above us. The rod is to be used upon the corpses of the three.\n\nFly now. We will have them as our own!", sourceObjective = "Baron Sliver at the Shadow Vault wants you to use the Sovereign Rod on the corpses of Vile, Lady Nightswood, and The Leaper.", progress = "You have NOT turned them yet. Do not insult my intelligence, {class}!", completion = "We will put those three to good use once we finally take the vault.\n\nSpeaking of which....", sourceObjectiveStatus = "unverified-source-field" }
quests[12894] = { id = 12894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crusader Forward Camp", description = "Crusader Dargath, Crusader MacKellar, Engineer Reed and the twins, Gerk and Burr, were sent to the Dead Fields to establish a battle front days ago. As of my last correspondence with them, they had successfully established a camp on the border of the Dead Fields, northwest of here.\n\nIn light of this newfound information about Drakuru and Prince Navarius I think it would be prudent to send someone to the Crusader Forward Camp post-haste.\n\nPack up your belongings, {name}. You must leave at once!", sourceObjective = "Seek out Crusader MacKellar at the Crusader Forward Camp in Zul'Drak.", completion = "Everything was fine until the Scourge attacked. They took off with Dargath, Gerk and Burr and they also destroyed our ride. Guess who led that attack?\n\n<MacKellar nods.>\n\nNavarius...\n\nSeems this whole area is some type of factory for Scourge. We're in the middle of a damned undead mine field!", sourceObjectiveStatus = "unverified-source-field" }
quests[12895] = { id = 12895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Bronzebeard", description = "Before we left, I received the file Scout Vor'takh compiled on this Brann Bronzebeard. There can be no doubt that Brann was headed for the Storm Peaks from his journal entries and findings in Grizzly Hills. Before we crashed, I caught sight of a campsite south of here, across the Foot Steppes, and overlooking the frozen Bor's Breath River.\n\nIf Brann isn't there, search the camp and its environs for any clues as to where that blasted dwarf might've gone. Bring back anything you find.", sourceObjective = "Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Boktar Bloodfury at the Grom'arsh Crash-Site.", progress = "Did you have any luck finding Bronzebeard's camp?", completion = "Of course, with our luck, I probably could've predicted this. Well, we're not going to let him get away that easily. Let's see what that note says.", sourceObjectiveStatus = "unverified-source-field" }
quests[12896] = { id = 12896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", sourceObjective = "Defeat General Lightsbane and then report your success back to Thassarian aboard the gunship, The Skybreaker.", completion = "General Lightsbane and his forces are defeated? The Shadow Vault is taken?", sourceObjectiveStatus = "unverified-source-field" }
quests[12897] = { id = 12897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", sourceObjective = "Defeat General Lightsbane and then report your success back to Koltira Deathweaver aboard the gunship, Orgrim's Hammer.", completion = "General Lightsbane and his forces are defeated? The Shadow Vault is taken?", sourceObjectiveStatus = "unverified-source-field" }
quests[12898] = { id = 12898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Thassarian gazes out over the horizon.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", sourceObjective = "Report back to Baron Sliver at The Shadow Vault.", completion = "Good of you to return. As you can see, we have our hands full here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12899] = { id = 12899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Koltira gazes down at the map on the floor.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", sourceObjective = "Report back to Baron Sliver at The Shadow Vault.", completion = "Good of you to return. As you can see, we have our hands full here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12900] = { id = 12900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Harness", description = "So you want to ride?  Well, if you've made it this far someone must think you've got a shot at the Hyldsmeet.\n\nFirst things first; we'll have to make you a harness.\n\nIn the cliffs to the south, you'll find scattered groups of yeti.  Their hides are tough and just the right thickness.  Bring me some and we'll get you started on the path of the bear-rider.", sourceObjective = "Astrid Bjornrittar in Brunnhildar Village wants you to obtain 3 Icemane Yeti Hides.", progress = "Did you find the hides yet?  You'll find yeti in the hills below.", completion = "These will do nicely.  I'll have the harness ready for you in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[12901] = { id = 12901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Something Out Of Nothing", description = "Prince Navarius must be stopped. We can't let the Scourge continue to use this area as a zombie factory. If we can get the tank operational we might stand a chance. What I need right now are spare parts.\n\nNorthwest of here is an area called Thrym's End. The Scourge armies are using the area as a base of sorts. Spread out across the base is the wreckage from their arrival. Bits and pieces of Scourge scrap metal litter the landscape. Get that stuff to me and I'll try and put it to good use.", sourceObjective = "Engineer Reed at Crusader Forward Camp in Zul'Drak has asked that you recover 10 pieces of Scourge Scrap Metal.", progress = "I really don't know if this plan will work, {name}. Just bring me the scrap metal and I'll do what I can.", completion = "What is this junk! Ah, damn it all! It's useless. Scourge metal isn't gonna do the trick. What are we going to do?", sourceObjectiveStatus = "unverified-source-field" }
quests[12902] = { id = 12902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search Of Answers", description = "These poor creatures are the only survivors.\n\nAccording to their chief, the Drakkari trolls and Rageclaw wolvar have been allies for thousands of years. They've been living here, alongside the trolls, for generations, completely unaware of the ever changing world around them. To the Rageclaw, a troll is a troll, so the troll attack upon their den took them by surprise.\n\nWe need some answers, {name}. Scour their village - southeast of here - for clues as to who or what is in charge of these attacks.", sourceObjective = "Search Rageclaw Den for a clue about who or what initiated the attacks against the Rageclaw Wolvar.", completion = "There is a scroll floating in the air above the strange altar. This must be what Crusader Lord Lantinga is looking for!", sourceObjectiveStatus = "unverified-source-field" }
quests[12903] = { id = 12903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's What Friends Are For...", description = "We were attacked by Prince Navarius and at least a dozen Scourge. I told Dargath and the twins to stay inside the tank, but they wouldn't listen. Dargath looked me in the eyes and said, \"If somebody doesn't get out of this tank, they'll kill us all.\" He then made Reed cut the engine and charged. Most heroic thing I've ever seen.\n\nI heard the Prince barking orders to the monsters. Sounded like he was taking them to Thrym's End, northwest of here. We have to rescue our friends. Will you go look for them?", sourceObjective = "Crusader MacKellar at Crusader Forward Camp has asked that you find Crusader Dargath, Gerk and Burr.", completion = "It was a great sacrifice that those three made and it won't soon be forgotten. Their passing will not be in vain. We will be victorious!", sourceObjectiveStatus = "unverified-source-field" }
quests[12904] = { id = 12904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Won't Grant Me Vengeance", description = "They... They killed my brother.\n\n<Gerk fights back tears.>\n\nSlaughtered him like he was some sort of animal. Now they got him laid out on one of their tables on the other side of the camp, ready for their grizzly experiments. Dargath's dead too. The paladin made a heroic stand at the ruins to the northeast, but the leader of the Vargul, Algar, was too strong.\n\nI'm all that's left and I'll be dead soon too. I... I'm turning.\n\nIf the Light won't grant me vengeance, maybe you will, {class}. Kill them all.", sourceObjective = "Gerk at Thrym's End in Zul'Drak wants you to kill 15 Vargul.", progress = "You're doing the world a favor, friend. These monsters must be stopped!", completion = "<Gerk is dying.>\n\nTh... They say these Vargul are the... the ones that weren't found worthy by the Lich King. Can... Can you im... imagine it? Just th... think how powerful the... the... worthy must be...\n\nI'll say a prayer for you in the hereafter, hero... May you never have to face them in number.", sourceObjectiveStatus = "unverified-source-field" }
quests[12905] = { id = 12905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mildred the Cruel", description = "Our deal is made then, {name}.  You help me get out of these chains and I'll help you find your little green friend.\n\nThe Hyldnir who runs this mine is known as Mildred the Cruel -- and with good reason.\n\nTell her you've been sent to lend a hand with the mines.  Do whatever she asks until she trusts you with the keys to my shackles.", sourceObjective = "Speak to Mildred the Cruel inside the Forlorn Mine.", completion = "I was expecting a replacement for one of my overseers.  It's about time you showed up.\n\nLet's put you to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[12906] = { id = 12906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discipline", description = "Let's start you off with something straightforward.  The male vrykul that work the mines for us do so against their will... purely out of fear of our blades.\n\nOnce in a while, one of them will lose their motivation.  Find any uncooperative vrykul and put them in their place.\n\nTake this disciplining rod.  You'll want to inflict pain, not death.  Well, most of the time anyway.", sourceObjective = "Mildred the Cruel at the Forlorn Mine wants you to use the Disciplining Rod on 6 Exhausted Vrykul.", progress = "Is it done?  I hope you didn't slay too many of the mongrels.  We need the manpower.", completion = "Not bad for a new overseer.  I've another task for you if you're feeling brave today.", sourceObjectiveStatus = "unverified-source-field" }
quests[12907] = { id = 12907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examples to be Made", description = "For every action there is an opposite reaction, sister.  In the case of us applying pressure on the males, this has meant newly spread rumors of insurrection.\n\nThe bearded pig behind this rabble-rousing is called Garhal.  Put an end to him... and make sure the other males see his demise.  They must learn that insubordination will not be tolerated.", sourceObjective = "Mildred the Cruel at the Forlorn Mine wants you to slay Garhal.", progress = "You're back.  Did you kill the insubordinate pig?", completion = "If I had any reservations regarding your commitment when you first arrived, I no longer have any.  With just a little more effort you could be a permanent member of my operation.", sourceObjectiveStatus = "unverified-source-field" }
quests[12908] = { id = 12908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Certain Prisoner", description = "You are without mercy.  You will do well around these parts.\n\nI have another task to ask of you.  There is a female vrykul prisoner that's become more of a liability than I had anticipated.\n\nShe had the gall to claim the right to take part in the Hyldsmeet, our sacred competition of strength and fighting prowess.\n\nHere's the key to her shackles.  Make it as painless as possible.  She's a female after all, even if not one of us.", sourceObjective = "Take Mildred's Key to Lok'lira the Crone in the Forlorn Mine.", progress = "It's about time.", completion = "I knew you'd be back!  Get me out of these shackles and I'll help you find the goblin.", sourceObjectiveStatus = "unverified-source-field" }
quests[12909] = { id = 12909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nose Knows", description = "In order to track down Brann, we're going to need a creature with a keen sense of smell and a good tracking ability. There weren't any hounds on the zeppelin, but I think I have a substitute.\n\nAfter the crash, I sent Khaliisi down the east face of the mountain to start hunting for food. Her cat, Frostbite, excels at tracking prey in the snow. Tell her that she'll have to part with her companion for a while, at least. She can hunt on her own, but we have no other way of catching up to Brann Bronzebeard.", sourceObjective = "Speak with Khaliisi at the foot of the mountain east of the Grom'arsh Crash-Site.", completion = "So Boktar has volunteered Frostbite for an errand, eh? Well, this had better be important. He knows better than to try to separate a hunter from her pet!", sourceObjectiveStatus = "unverified-source-field" }
quests[12910] = { id = 12910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Out the Perpetrator", description = "Boktar can have his way this time, but I'll expect him to make it up to me. Don't look at me like that. Boktar may be in command, but no one tells a hunter what to do.\n\n'Put that beast away,' he says. 'Make it stop growling.'\n\nAll of a sudden he changes his mind when it suits him. Next time he complains, Frostbite'll just nip him a bit. Don't worry, she'll do an admirable job tracking your prey. After she locates her target, you're on your own to deal with iron dwarves, or Brann, or whatever you find.", sourceObjective = "Mount Frostbite and ride her to the source of the scent from Brann's note. Then, recover Brann's Communicator and use it to make contact with Brann Bronzebeard.", progress = "Who... who're you?", completion = "<An image of a dwarf appears as you activate the communicator. It can only be Brann Bronzebeard.>\n\n<From the look on his face, Brann seems shocked to see you and begins gesturing furiously.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12911] = { id = 12911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Credit Test", description = "/wave at me and I'll assign 'kill credit to player' to you.", sourceObjective = "/wave at Kill Credit Test", sourceObjectiveStatus = "unverified-source-field" }
quests[12912] = { id = 12912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Storm Approaches", description = "You are not like the others, little one. You do not reek of the ancient death. Perhaps you can be trusted.\n\nI am Gymer, king of the storm giants. I was lured here by my brother, Thiassi, now an undead servant of the Lich King. By the time I realized that his cry for help was a trap, it was too late. I am now a prisoner of the Scourge and I fear that soon I will suffer the same fate as many of the other storm giants.\n\nFind a way to release me from this cage and I will aid you to the best of my ability.", sourceObjective = "Gymer, King of Storm Giants, has asked you to find a way to release him from his cage. Speak with Engineer Reed at the Crusader Forward Camp.", completion = "A... A storm giant? I don't know about this, {name}. That sounds risky. On the other hand, I don't think we have too many other options.\n\nIf I do this you have to promise me that you will get your giant friend to help us deal with Navarius and his cronies.", sourceObjectiveStatus = "unverified-source-field" }
quests[12913] = { id = 12913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak Orcish, Man!", description = "<Brann begins gesticulating wildly and rambling in his native language.>\n\nRuk MogOth red a mogoth ta eft Thros-garE Haldir.\n\nKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.\n\nA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.\n\n Gar Ruk dagUm loch angor-magi ta har ruk!\n\n<After a few moments, you realize the conversation is going nowhere. Perhaps the shaman, Moteha Windborn, at the Grom'arsh Crash-Site will know what to do.>", sourceObjective = "Speak with Moteha Windborn at the Grom'arsh Crash-Site.", completion = "Boktar will not be happy that you didn't find Brann, but at least you didn't come back empty-handed. Now, let's see what we can do about this babbling dwarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12914] = { id = 12914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gymer's Salvation", description = "Now you say that he's locked up in a 100 foot tall cage, eh?\n\nIf my calculations are correct, we should be able to at least weaken the hinges on the cage, giving the giant enough leeway to break out.\n\nIf this is going to work I'm going to need some plasticizers and stabilizers.\n\nBanshee essence should do nicely for the plasticizer. You can get that from the banshees in the Dead Fields, northeast of us. The stabilizer can be found on the earthragers to the southwest, near Ebon Watch.\n\nGet a move on!", sourceObjective = "Engineer Reed at Crusader Forward Camp in Zul'Drak wants you to bring him 6 Banshee Essence and 6 Diatomaceous Earth.", progress = "Without the plasticizers and stabilizers I'll never be able to make the explosives necessary to break your friend out of jail.", completion = "Thankfully we weren't in short supply of explosives. Putting together the jumbo seaforium charge should be no problem with the materials you brought me.", sourceObjectiveStatus = "unverified-source-field" }
quests[12915] = { id = 12915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Fences", description = "If I hope to wrest control of the Temple of the Makers from my brother, I must make amends with my old allies.\n\nPerhaps by eliminating a common enemy, we may at least take a step towards renewing my friendship with the frost giants.\n\nFjorn has besieged Dun Niffelem with giants of iron. You must defeat him at Fjorn's Anvil, far to the east of here, and weaken his forces sufficiently for the Sons of Hodir to emerge victorious.\n\nTake this charm, {name}. Use it to summon my earthen to your aid.", sourceObjective = "Thorim at the Temple of Storms wants you to Kill Fjorn and 5 Stormforged Iron Giants at Fjorn's Anvil, east of Dun Niffelem.\n\nUsing Thorim's Charm of Earth will summon his Earthen to fight by your side. The charm requires a Granite Boulder from nearby Fjorn's Anvil.", progress = "Does Fjorn still live, {class}?", completion = "So, it is done then.\n\nLet us hope it is enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[12916] = { id = 12916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Only Hope", description = "What I'm about to give you is called seaforium. It is a highly volatile explosive with some unique properties. Due to its malleable nature, you will be able to fill in the hinges and cracks of the cage for maximum damage.\n\nReturn to your friend and use the jumbo seaforium charge to set him free.\n\nLet's hope he honors the bargain. He's our only hope.", sourceObjective = "Speak to Gymer at Thrym's End in Zul'Drak once you have used the Jumbo Seaforium Charge to open the Scourge Enclosure that is holding him prisoner.", progress = "I am a giant of my word, little one.", completion = "FREEDOM!\n\nDo not be afraid, little one. Gymer is an honorable giant. Like you and your people, I too wish to see the Scourge driven away from this land and the Lich King destroyed. I will help you, as promised, to the best of my ability.", sourceObjectiveStatus = "unverified-source-field" }
quests[12917] = { id = 12917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking with the Wind's Voice", description = "I suppose we shouldn't have expected to find Brann so easily, not with our luck. If we can make sense of what Brann is saying, you can persuade him to give up his location.\n\nThe power of the wind is strong in these mountains, and it may prove a great boon to us. A knowledgeable shaman can hear the sound of all the world's tongues on the wind.\n\nTo the northwest, on the Snowdrift Plains, you will find beings made of wind, the stormriders. Capture their voices and bring them to me.", sourceObjective = "Bring 5 Voices of the Wind to Moteha Windborn at the Grom'arsh Crash-Site.", progress = "Have you brought the wind's voices?", completion = "You should be able to communicate with the dwarf now. Ask Boktar what he requires of you. There is little time to lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[12918] = { id = 12918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "It has the cold of the Icewyrm's breath up here does it not?   Not only do I lack customers for my crafting skills, but I also lack stock of gems to sell!   If you can bring me several uncut gems to replenish my stocks, I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Ounhulo in Valgarde.", progress = "You are most generous.   The least I can do is to teach you the skills of gem perfection.", completion = "These are perfect for replenishing my stock.   Not only will I teach you the art of gemcutting perfection, but I cut one of them gems into its perfect form which you may have as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[12919] = { id = 12919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm King's Vengeance", description = "My people have been decimated by the Lich King. The Scourge now use the corpses of storm giants to create mindless flesh giants, or worse, stitched together aberrations like Thrym.\n\nI will stop at nothing to see them all driven from this world. We will work together to destroy the Scourge that threaten Zul'Drak.\n\nWe will kill them all: Navarius, Algar and Thrym!\n\nWhen you are ready, let me know and we will begin our destructive journey.", sourceObjective = "Speak with Gymer to begin.\n\nWhile riding Gymer, destroy 100 Scourge and kill Algar the Chosen, Thrym and Prince Navarius. Report to Crusader MacKellar at Crusader Forward Camp should you succeed.", progress = "What is going on? Are our enemies dead?", completion = "Unbelievable! This will be a story for the ages, {name}! One man rode upon the head of the king of storm giants and decimated an entire Scourge army!\n\nAnd I was there to see it all happen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12920] = { id = 12920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching up with Brann", description = "What are you waiting for? The language barrier has been broken, thanks to Moteha. Contact Brann Bronzebeard and find out anything you can about where he's hiding and what he's chasing after.\n\nMaybe we can still salvage something from this disaster.", sourceObjective = "Use Brann's Communicator to contact Brann Bronzebeard and speak with him, then speak to Boktar Bloodfury at the Grom'arsh Crash-Site.\n\nIf you lose Brann's Communicator, speak with Moteha Windborn at the Grom'arsh Crash-Site.", progress = "What did you find out?", completion = "<Boktar listens as you describe your conversation with Brann.>\n\nThere's truth to the dwarf's words. Vor'takh's plan is not the way of the Horde. If Brann Bronzebeard knows of a way to stop these iron dwarves and their patron, it serves us to help him.", sourceObjectiveStatus = "unverified-source-field" }
quests[12921] = { id = 12921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Scenery", description = "Excellent.  There's an exit in the eastern end of the mine that leads to Brunnhildar Village.  Follow it and I'll meet you there.\n\nWe must not be seen together so no one suspects you of aiding me.  I'll use my magic to disguise my appearance.  Do not worry, {race} -- we'll find your friend in no time.", sourceObjective = "Reconvene with Lok'lira the Crone in Brunnhildar Village.", completion = "You're here -- good.  I think I know where your goblin is.", sourceObjectiveStatus = "unverified-source-field" }
quests[12922] = { id = 12922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Refiner's Fire", description = "Beneath its porous exterior, this hunk of metal gleams with a mysterious quality.\n\nYou feel it would only be prudent to burn off the slag at Fjorn's Anvil.\n\nAs you ponder where in this frozen waste you might find something hot enough for the job, a fire revenant crosses your path...", sourceObjective = "You must collect 10 Furious Sparks from the Seething Revenants at Frostfield Lake and then use the anvil at Fjorn's Anvil.", progress = "The surface of the anvil is scalding, in sharp contrast with the wintry air.", completion = "You place the metal on the anvil and immediately upon adding the sparks they work the ore furiously.\n\nWhen at last they burn out, you are left with a large piece of metal that gleams with a light of its own.", sourceObjectiveStatus = "unverified-source-field" }
quests[12924] = { id = 12924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging an Alliance", description = "<Thorim, for the first time since your meeting him, smiles.>\n\nThis is all beginning to have the smell of fate's hand, {race}.\n\nYour discovery is what remains of my armor, long ago cast off in a fit of grief and left to the elements. Only the sons of Hodir are capable of its reforging, for they are its original creators.\n\nPerhaps you've done enough to soften their hatred of me. Seek out their king, Jokkum, if he still breathes.\n\nFind your way into his good graces and plead for his assistance.", sourceObjective = "You are to go to Dun Niffelem and ask King Jokkum to allow Thorim's armor to be reforged. After completing Jokkum's task, you are to speak with Njormeld in Dun Niffelem.", completion = "It would seem that I have refined my technique considerably. That, or the legends surrounding this anvil are true.\n\nThis suit of armor is superior to the last, and took less material to create.\n\nWith the excess, I was able to fashion you a little something as payment for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12925] = { id = 12925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrations", description = "The Lich King sent emissaries to us on three different occasions.  All three were promptly dismembered.\n\nOur sisters in Valkyrion were not as dedicated to our traditions and accepted the Scourge's advances.  Now instead of capturing their drakes from the wild, they raise them from the blight and filth that the Scourge wallow in.\n\nTake the frost oil that the Valkyrion Hyldnir carry on them and use it to freeze any blighted eggs you find.  Rumors speak of a fetid pool of blight where the eggs are kept.", sourceObjective = "Thyra Kvinnshal in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants. Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.", progress = "Did you destroy the blighted eggs?", completion = "You have our thanks, sister.  We cannot allow our valiant traditions to be corrupted.", sourceObjectiveStatus = "unverified-source-field" }
quests[12926] = { id = 12926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of the Puzzle", description = "We've seen the iron dwarves and their constructs making war on the creatures of stone that Brann calls the earthen, along with their giant allies. Contact him and aid him in any way you can, and remember that anything we can learn from his search may aid us in fighting against the iron dwarves and their master.", sourceObjective = "Use Brann's Communicator to contact Brann Bronzebeard and find out what to do next.", progress = "Did you complete the disk?", completion = "That was quick! Now that we have the disk, we have to find out how to use it to unlock the first half of the archive key.", sourceObjectiveStatus = "unverified-source-field" }
quests[12927] = { id = 12927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Mining", description = "That disk you assembled... it's blank! Keeper Mimir, the tinker who built this library, must've hidden the information elsewhere. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be the disk's purpose. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", sourceObjective = "Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks.", progress = "Did you try using the disk? What did you find?", completion = "<Brann looks at the disk as you hold it up.>\n\nI can't tell if there's anything stored there or not, lad. You'll have to tell me what happened.\n\n<You describe the data retrieval process.>\n\nSo it worked? At least we can count on Keeper Mimir to be systematic.", sourceObjectiveStatus = "unverified-source-field" }
quests[12928] = { id = 12928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", sourceObjective = "Recover Norgannon's Shell from Archivist Mechaton.", progress = "Did you find Norgannon's shell?", completion = "That's it! That's the first half of Norgannon's keystone. Well done, {name}. I've had Archaeologist Andorin on the lookout for clues to the shell's whereabouts for a long time. He's never going to believe me when I tell him it was an intrepid {race} who found it instead.", sourceObjectiveStatus = "unverified-source-field" }
quests[12929] = { id = 12929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen of Ulduar", description = "The earthen who once inhabited, built, and maintained Ulduar were ousted from their home when Loken took over the city. Since then, his iron dwarf followers have relentlessly attacked the exiles.\n\nThey have taken refuge in an old titan building, which they now call Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren fight to keep the irons from overrunning their haven, but they cannot hold their ground long. Find and help them, {name}.", sourceObjective = "Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "So you know Brann Bronzebeard, then? He is our closest ally among those of the flesh. We are as brothers in the struggle against Loken and his followers, in the fight for Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12930] = { id = 12930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Earth", description = "It seems so long ago that these hammers pounded and hewed stone instead of iron. Our expulsion from Ulduar saw the weakest of us dead and the strongest of our craftsmen reborn as warriors.\n\nAs the irons beat us back, even the strongest find themselves failing.\n\nWe can do little for the wounded, save when we have a stock of enchanted earth. We used to mine it from the deposits on the sheer cliff face to the northwest, but the constant battle has prevented us from replenishing our stock. Would you help?", sourceObjective = "Use the Earthen Mining Pick to mine 7 clumps of Enchanted Earth. Bring the earth and 5 Frostweave Cloth to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Were you able to find any of the earth?", completion = "This will allow us to patch up more of the fallen. Thank you, {name}, on behalf of all who defend the refuge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12931] = { id = 12931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Back", description = "The refuge's defenders have done their best to blunt the iron dwarves' attacks, but we keep losing ground inch by inch. My men are hardy, but not tireless. Without reinforcements, it's only a matter of time until we will be overrun.\n\nWould you lend your skills to the refuge's defense? It would greatly improve the morale of the defenders and give them -- and me -- hope of mounting a counterattack.\n\nKill any of the stormforged or their creations you encounter outside the refuge.", sourceObjective = "Bouldercrag the Rockshaper wants you to slay 10 Stormforged Attackers and return to him at Bouldercrag's Refuge. You may kill either Stormforged Raiders or Stormforged Reavers.", progress = "How goes the battle?", completion = "You've given the defenders something to cheer about. Seeing the enemy fall by your hand has reinvigorated them and bolstered their courage.", sourceObjectiveStatus = "unverified-source-field" }
quests[12932] = { id = 12932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Yggdras!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand. These trolls are dirtier than ogres; but hey, I go where the gold's at! So welcome to Zul'Drak, pal.\n\nYou're new to this racket, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[12933] = { id = 12933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Magnataur!", description = "This next match is a doozy, buddy! Apparently some magnataur from the Dragonblight wants a piece of the action. You ever fought one of those before? All I can tell you is to aim high!\n\nWe'll get this party started when you give me the word.", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Stinkbeard! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Wow! When I first saw Stinkbeard, I thought you were done for! Nice work!", sourceObjectiveStatus = "unverified-source-field" }
quests[12934] = { id = 12934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: From Beyond!", description = "I'm not gonna lie to you, pal. You might be overmatched here. This next one is a being from the elemental planes! I don't even know what's gonna show up in that arena!\n\nIf you think you're up to it, get in there and give 'em hell!", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat one of the elemental lords! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Unbelievable! I thought this whole place was going to explode when it first appeared! You really dominated that round!", sourceObjectiveStatus = "unverified-source-field" }
quests[12935] = { id = 12935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Tuskarrmageddon!", description = "This next one's fightin' from a dark place, kid. The kind of dark that can only happen when you've been on the flip-side. He's hungry and willing to do whatever it takes to win. Watch yourself! I've heard he wrestles yetis for exercise!\n\nWe'll start when you're ready.", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Orinoko Tuskbreaker! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "I was worried for a while there, {name}. When he busted out the seals and penguins... Well, I didn't know what to think to be honest. It looked pretty damn ridiculous.", sourceObjectiveStatus = "unverified-source-field" }
quests[12936] = { id = 12936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Korrak the Bloodrager!", description = "You're not gonna believe this, pal. Your next fight is against Korrak the Bloodrager! Looks like the Drakkari trolls are pulling a power play! And let me tell you, buddy, he's been sippin' the animal god juice. He's good and ready to pound you into the ground.\n\nAre you ready?", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Korrak the Bloodrager! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Damn, I remember Korrak from way back in my younger days when I used to work for the Frostwolf Clan. He would never shut up! I think you just did the world a great service, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12937] = { id = 12937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relief for the Fallen", description = "The refuge's defenders fight bravely, but they cannot keep up with the iron onslaught.\n\nWith the earth you collected, I can make bandages to help heal the wounds of some of the fallen. The more defenders we can patch up, the longer we'll last out there.\n\nTake these poultices and use them to heal the wounds of the fallen defenders outside the refuge. Get as many back into the battle as possible, {name}. Every casualty is one too many.", sourceObjective = "Use the Telluric Poultice to heal 8 Fallen Earthen Defenders, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Have you healed the fallen defenders?", completion = "The warriors that you've healed will aid us in holding the line even longer. If we are to truly be free of the iron threat, we must find a way to strike at them behind the lines.", sourceObjectiveStatus = "unverified-source-field" }
quests[12938] = { id = 12938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Duke", description = "We need you focused, {name}. We're barely holding The Shadow Vault as it is. As you can see, we've greatly angered the Lich King.\n\n<The baron chuckles.>\n\nI need you to speak with Duke Lankral. He's in charge here now. You'll find him inside the vault building proper.\n\nWere I you, I would not keep him waiting.", sourceObjective = "Speak with Duke Lankral at The Shadow Vault.", completion = "It's a pleasure to finally meet you, {name}. We owe you a great deal, but we're not done with you yet.\n\nThere is a vrykul city just over the mountains to the west, a place called Jotunheim.\n\nThe vrykul there are in a constant state of challenge to 'ascend'. The winners go to Ymirheim to serve as the Lich King's elite warrior caste, the Ymirjar, and the losers are reduced to scourged Vargul.\n\nYou are going to be my instrument to see to it that more Vargul than Ymirjar emerge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12939] = { id = 12939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Challenge", description = "The first step we're going to take is at a place in Jotunheim called the Savage Ledge. It's just over the mountains to the west.\n\nOn the ledge the vrykul warriors are always sparring, being instructed in the finer arts of battle by their thane's men.\n\nI want you to take this flag and issue a challenge to a number of them. Let's demoralize them with the 'mere' skills of a {race}, shall we?\n\n<The duke grins, his rotting teeth flashing in the dim light of the vault.>", sourceObjective = "Duke Lankral at The Shadow Vault has asked you to use the Challenge Flag to challenge and defeat 6 Mjordin Combatants.", progress = "Perhaps you could go back and challenge a few more?", completion = "Already I'm hearing reports of the prowess you displayed on the Savage Ledge. Excellent, {name}... excellent!\n\n\n\nAnd now I think it's time to issue a decree to the thane of those vrykul that you so easily defeated.", sourceObjectiveStatus = "unverified-source-field" }
quests[12940] = { id = 12940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12941] = { id = 12941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12942] = { id = 12942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off With Their Black Wings", description = "Traitors.  We Hyldnir have little love for them.\n\nThe dwellers of Valkyrion have gone unpunished for far too long.  While we remained loyal to Thorim, they became the Lich King's lapdogs!\n\nThey call the ones who receive his gift val'kyr.  They fly on feathered wings, like the harpies they are.\n\nYou will find Valkyrion far to the northwest, beyond the Temple of Storms.  Slay these winged she-wolves, sister.  Slay them and I will reward you with one of my most prized possessions.", sourceObjective = "Iva the Vengeful in Brunnhildar Village wants you to go to Valkyrion and slay 12 Nascent Val'kyr.", completion = "The val'kyr are nothing but the Lich King's lapdogs.  They will be put down like the scum they are.  They've made their choice, now they have to live with the consequences.", sourceObjectiveStatus = "unverified-source-field" }
quests[12943] = { id = 12943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Vault Decree", description = "Thane Ufrang the Mighty sits within his hall overlooking the Savage Ledge. I've studied him. The thane is a patient vrykul, with a head for strategy and warfare. He's also shown a penchant for biding his time and not wanting to overplay his hand in the ongoing battle.\n\nI need him dead!\n\nI've written a decree. Stand before the thane and read it aloud.\n\n<The duke arches his eyebrow in amusement.>\n\nIt should... unnerve him at the least.", sourceObjective = "Duke Lankral at The Shadow Vault has ordered you to read the Shadow Vault Decree in the presence of Thane Ufrang the Mighty, and then to slay him.", completion = "<Duke Lankral nods his approval at your report of success.>\n\nWe face a foe that dwarfs us, not only in stature, but also numerically. If we are to win the battle for Icecrown, we must outthink them!\n\nWith Ufrang dead, that gives us an advantage in Jotunheim. Let us see if we can capitalize on it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12944] = { id = 12944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12945] = { id = 12945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12946] = { id = 12946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12947] = { id = 12947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12948] = { id = 12948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion of Anguish", description = "This is the end, my friend! Your last opponent is going to be your greatest challenge. He's a vrykul champion from the steppes of Icecrown and he's out for blood! Defeat him and you'll be crowned the champion of the Amphitheater of Anguish! This fight is going to make us both rich!\n\nLet me know when you're ready and we'll start.", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Vladof the Butcher! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "You did it, {name}! That was the most exciting fight yet! What are you going to do with your winnings? Me? I'm going to Dalaran and blowing it all in the Underbelly. Lot of hot action going on down there!", sourceObjectiveStatus = "unverified-source-field" }
quests[12949] = { id = 12949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Key", description = "{class}, the key to my shackles is hanging around the neck of Instructor Hroegar outside.\n\nPerhaps you could retrieve it by separating his head from his shoulders?", sourceObjective = "Vaelen the Flayed at Ufrang's Hall has asked you to retrieve the Key to Vaelen's Chains.", progress = "Do you have it?", completion = "Thank you, {race}. Just hand me the key, I'll take care of it myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[12950] = { id = 12950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12951] = { id = 12951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Baron Know", description = "The most important thing that you can do right now is to return to The Shadow Vault and let Baron Sliver know that I've failed.\n\nYou see, I wasn't the only one captured by these vrykul devils. My entire contingent of death knights was also taken.\n\nI should have seen the trap before it was sprung, but there's no use crying over spilled milk now is there?\n\nGo on before you get captured, too! I'll see you back at the vault.", sourceObjective = "Speak with Baron Sliver at The Shadow Vault.", completion = "What?! We can ill-afford to lose one death knight, let alone an entire contingent!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[12952] = { id = 12952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "My skills are going to waste in this wretched place.   I spent many years learning to cut gems into their perfect form and have nothing to work on!   You look like the type who may be able to find me some gems and if you do I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Carter Tiffens in Vengeance Landing.", progress = "These will do.   I shall teach you the skills of gem perfection.", completion = "These will have to do.  I can teach you the art of gemcutting perfection, and give you proof of my skills as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[12953] = { id = 12953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valkyrion Must Burn", description = "The crate is filled with incendiary harpoons.  You recall seeing harpoon guns and dry stacks of hay outside.\n\nPerhaps Iva will appreciate the extra effort and reward you appropriately.", sourceObjective = "Use the Valkyrion Harpoon Guns to burn 6 Dry Haystacks.", completion = "Now that is what I call dedication!  Those traitors might have a new master now, but they'll never forget their sisters' parting gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[12954] = { id = 12954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Yggdras!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this dump is Zul'Drak. All the ice trolls seem to use it as a toilet. I dunno, the whole place is off its rocker if you ask me! Who cares, though, right? We're here to make some gold!\n\nYou know the drill, {name}. When you're ready let me know and we'll get this show on the road!", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Hey! I know you. Your victory at the Ring of Blood was talked about for months! Too bad you forfeited the championship when you failed to show up to defend your title! Easy come, easy go, eh? At least you're still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[12955] = { id = 12955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Competition", description = "Mrrfrmrfrrmrrr...\n\n<The Leaper clears his throat.>\n\nSorry about that. It can sometimes be hard to understand what I'm saying. You know how it is.\n\nI wanted to make sure that if you find yourself at the Savage Ledge, over the mountains to the west, that you make sure to eliminate the competition there.\n\nSpecifically, I'd like you to challenge to duels and humiliate Sigrid Iceborn, Efrem the Faithful, Onu'zun, and Tinky Wickwhistle in front of the vrykul.", sourceObjective = "The Leaper at The Shadow Vault wants you to duel and defeat Sigrid Iceborn, Efrem the Faithful, Onu'zun and Tinky Wickwhistle.", progress = "Why are you here?\n\nGo and humiliate them!", completion = "That was important, {name}. By driving them off, you're keeping them from interfering with whatever we need you to do over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[12956] = { id = 12956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spark of Hope", description = "Clearly, this is more than an ordinary hunk of metal.\n\nUnlike any ore you're familiar with, it is hard but not brittle, far lighter than it looks, and glows even when cool.\n\nLooking closer, you can make out one of Thorim's runes shining beneath the surface....", sourceObjective = "You are to bring the Refined Gleaming Ore to Thorim in the Temple of Storms.", progress = "What have you there, little one?", completion = "You notice Thorim's stern countenance brighten with recognition as you present the ore.", sourceObjectiveStatus = "unverified-source-field" }
quests[12957] = { id = 12957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves of the Stormforged", description = "To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.\n\nI don't know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.\n\nGo to the Frozen Mine, {name}, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.", sourceObjective = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to free 6 Captive Mechagnomes and kill 3 Stormforged Taskmasters.", progress = "Have you freed the slaves of the stormforged?", completion = "I had hoped that more of the captives would choose to join us, but I do not blame them. Willing allies are few and far between, and we are thankful that you have lent your blade to our cause.", sourceObjectiveStatus = "unverified-source-field" }
quests[12958] = { id = 12958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Blood Jade Amulet", description = "A wealthy shipping concern has requested a collection of Blood Jade Amulets to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine a Vrykul Amulet, a Dark Jade and a Bloodstone to make a Blood Jade Amulet and bring it to Timothy Jones in Dalaran.\n\nYou can find a Vrykul Amulet on any Northrend Vrykul.", progress = "Do you have a Blood Jade Amulet for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12959] = { id = 12959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Glowing Ivory Figurine", description = "A wealthy shipping concern has requested a collection of Glowing Ivory Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine Northern Ivory, a Chalcedony and a Shadow Crystal to create a Glowing Ivory Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Northern Ivory on any Shoveltusk or Mammoth in Northrend.", progress = "Do you have a Glowing Ivory Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12960] = { id = 12960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Wicked Sun Brooch", description = "A wealthy shipping concern has requested a collection of Wicked Sun Brooches to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine an Iron Dwarf Brooch, a Huge Citrine and a Sun Crystal to create a Wicked Sun Brooch and bring it to Timothy Jones in Dalaran.\n\nYou can find an Iron Dwarf Brooch on any Northrend Iron Dwarf.", progress = "Do you have a Wicked Sun Brooch for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12961] = { id = 12961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Intricate Bone Figurine", description = "A wealthy shipping concern has requested a collection of Intricate Bone Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine a Proto Dragon Bone, a Sun Crystal and a Dark Jade to craft an Intricate Bone Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Proto Dragon Bone on any Northrend Proto Dragon.", progress = "Do you have an Intricate Bone Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12962] = { id = 12962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Bright Armor Relic", description = "A wealthy shipping concern has requested a collection of Bright Armor Relics to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine an Elemental Armor Scrap, a Bloodstone and a Huge Citrine to craft a Bright Armor Relic and bring it to Timothy Jones in Dalaran.\n\nYou can find an Elemental Armor Scrap on any Northrend Revenant.", progress = "Do you have a Bright Armor Relic for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12963] = { id = 12963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Shifting Sun Curio", description = "A wealthy shipping concern has requested a collection of Shifting Sun Curios to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine a Scourge Curio, a Sun Crystal and a Shadow Crystal to make a Shifting Sun Curio and bring it to Timothy Jones in Dalaran.\n\nYou can find a Scourge Curio on any Northrend Scourge.", progress = "Do you have a Shifting Sun Curio for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12964] = { id = 12964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Ore", description = "At the Frozen Mine in the western part of the Snowdrift Plains, the stormforged iron dwarves have constructed a mine manned by slaves.\n\nIt's well behind the lines, so we haven't been able to find out much about what's going on there, but my scouts have reported seeing them remove cartloads of dark, sickly looking ore.", sourceObjective = "Bring 5 Ore Samples to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "What have you discovered about the ore?", completion = "<Bouldercrag reaches out to take the ore, but then recoils.>\n\nThat ore... I can't touch it. It seethes with unnatural energy. No creature of stone can handle it. What do they mean to do with this?", sourceObjectiveStatus = "unverified-source-field" }
quests[12965] = { id = 12965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gifts of Loken", description = "The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.\n\nIt could explain the strength and ferocity my men see in the stormforged warriors.\n\nValduran's base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, {name}, and neutralize his power. Destroy these gifts of Loken's and help us to sap the strength of his followers.", sourceObjective = "Destroy Loken's Fury, Loken's Power, and Loken's Favor, and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Is it true? Does Valduran possess powerful relics of the titans? Did you destroy them?", completion = "<Bouldercrag nods grimly.>\n\nYou've weakened the stormforged considerably, but they'll keep fighting. Their casualties matter nothing to them, while our defenders continue to fall. Even if it costs them a hundred or a thousand iron corpses, they'll keep fighting until we've been pounded to gravel.", sourceObjectiveStatus = "unverified-source-field" }
quests[12966] = { id = 12966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can't Miss Him", description = "<Jokkum listens patiently to your request, then ponders it carefully before responding.>\n\nSo it is you we have to thank for Fjorn's demise?\n\nWhile it's true that you have aided us in our time of need, there is still much that must be done to repair our relations with Thorim.\n\nFor now, I shall allow Njormeld to reforge the armor we gifted to the Stormlord so many ages ago. Consider it payment for your assistance against Fjorn.\n\nNjormeld was sent to recover Fjorn's anvil. You should find him there.", sourceObjective = "King Jokkum in Dun Niffelem wants you to find Njormeld at Fjorn's Anvil.", completion = "Reforging Thorim's armor? It can be done.\n\nFirst though, there's the matter of the anvil...", sourceObjectiveStatus = "unverified-source-field" }
quests[12967] = { id = 12967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battling the Elements", description = "Snorri was once the pride of our nation. A mighty warrior, many an enemy fell to his club.\n\nWe honor him, though he's no longer what he once was. Age has taken its toll, dulling his senses and sapping his strength. Still, he remains as proud as ever, never missing an opportunity to join a battle.\n\nSpeaking of battle, we're cooling Fjorn's anvil so it can be taken home. The remaining fire revenants are putting up some resistance. Help Snorri relive his glory days, {race}. Guide him against this enemy.", sourceObjective = "Njormeld wants you to accompany Snorri to Fjorn's anvil and help him kill 10 Seething Revenants.", progress = "Were you able to lead Snorri to another victory, {class}?", completion = "An honorable performance, {race}. I shall inform the king of your assistance.\n\nThe anvil is nearly cool enough. I shall see you in Dun Niffelem soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12968] = { id = 12968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yulda's Folly", description = "The witch that started it all, Yulda the Stormspeaker came to our very village.  She dared to insult our noble traditions and spouted the Lich King's venomous promises of power.\n\nShe ought to have left with a sword through her, but her magic was strong and she managed to escape.\n\nSeek her in Valkyrion inside the largest dwelling and show her that we are not to be trifled with.", sourceObjective = "Iva the Vengeful at Brunnhildar Village wants you to slay Yulda the Stormspeaker in Valkyrion.", progress = "Did you find Yulda?", completion = "Yulda had it coming.  No one gets away with insulting the Hyldsmeet.  Not even one of our own.", sourceObjectiveStatus = "unverified-source-field" }
quests[12969] = { id = 12969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is That Your Goblin?", description = "I trust that's the green little one you've been looking for.  If I were you I'd step in before that Hyldnir splits him in half.\n\nYou've arrived in the middle of the Hyldsmeet, so all challenges must be accepted by participants.  There's nothing to stop you from taking your green friend's place.", sourceObjective = "Challenge Agnetta Tyrsdottar in order to save Zeev Fizzlespark. Return to Lok'lira the Crone in Brunnhildar Village after you've succeeded.", progress = "You're back.", completion = "Well done, young one.  It looks like our deal has been satisfied on both our ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[12970] = { id = 12970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hyldsmeet", description = "Whether you've noticed or not, by defeating your first Hyldnir in hand-to-hand combat, you've entered the Hyldsmeet -- the great competition of Hyldnir against Hyldnir to determine who will rule by Thorim's side.\n\nThe Hyldsmeet is the reason why I was imprisoned, for I sought to partake in the competition but was far too old and frail to be a match for the Hyldnir.\n\nIf you're willing to listen, I've a proposal for you.", sourceObjective = "Listen to Lok'lira the Crone's proposal.", progress = "Keep it down, the others might start getting suspicious.", completion = "It's settled then.  You will compete in the Hyldsmeet and with my help you'll restore great Thorim to his rightful place.", sourceObjectiveStatus = "unverified-source-field" }
quests[12971] = { id = 12971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking on All Challengers", description = "Let's get you started.  The good news is that by defeating Agnetta, you've earned yourself a spot in the next round of matches.\n\nThe bad news is that all your opponents will also have defeated someone in the first round.  Do not expect pushovers.", sourceObjective = "Lok'lira the Crone in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", progress = "Yes, {name}?", completion = "You've done it, {name}.  You've bested some of the fiercest fighters the Hyldnir race has to offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12972] = { id = 12972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Need a Bear", description = "You've succeeded in the first rounds of the Hyldsmeet.  To advance further, you're going to need a warbear of your own.\n\nUnfortunately, the Hyldnir don't give them out to just anyone.  You'll have to emerge victorious from true battle, not just gladiatorial combat.\n\nThe Hyldnir of Brunnhildar are currently involved in a feud against the Sons of Hodir, Thorim's former allies.  Speak to Brijana just outside the village and see how you can help them and prove yourself in the process.", sourceObjective = "Speak to Brijana outside Brunnhildar Village.", completion = "Think we'll give you your own bear just like that?  You'll have to prove yourself before you get anything from us.\n\nDo not think too highly of yourself just because you bested a few challengers in the Hyldsmeet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12973] = { id = 12973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!", sourceObjective = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", progress = "My pardons, lad! I got all caught up in tha moment and I neglected ye entirely.", completion = "King Stormheart sends his most sincere thanks for reuniting him with his brothers. It seems he's off to settle a score now - perhaps you'll meet with him again on Arthas's doorstep.", sourceObjectiveStatus = "unverified-source-field" }
quests[12974] = { id = 12974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion's Call!", description = "Pfft, what happens down here ain't fightin'. It's a couple of guys dancin' around a flag.\n\nYou lookin' for some real action, buddy? 'Cause if you are I got the hottest ticket in town.\n\nEver heard of Gurgthock and Wodin? Goblin and troll who ran the Ring of Blood back in Outland? Well they're here in Northrend and they've started up a whole new fight club over in Zul'Drak. If you're interested go to Zul'Drak, east of Crystalsong. They're at the big arena in the center. Tell 'em Shifty sent ya!", sourceObjective = "Seek out Gurgthock at the Amphitheater of Anguish in Zul'Drak.", completion = "Shifty sent you, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[12975] = { id = 12975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Memoriam", description = "Surely Thorim has told you of the tragedy that divides us.\n\nIt was in Thunderfall, northeast of here, that these events unfolded. The frozen fossils there are a reminder of that dark day, as are the spirits that haunt that place.\n\nIf my people are to forgive Thorim, something must take the place of those images. A memorial must be constructed to bring our hearts peace.\n\nGo there, {race}. Collect the fragments of Hodir's Horn that was shattered that day.", sourceObjective = "King Jokkum in Dun Niffelem wants you to collect 8 Horn Fragments from Thunderfall.", progress = "Have you found the pieces of Hodir's Horn?", completion = "Another good deed you have done on Thorim's behalf, {class}.\n\nThis will help to soften the hearts of my people towards him.", sourceObjectiveStatus = "unverified-source-field" }
quests[12976] = { id = 12976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monument to the Fallen", description = "Bring these fragments to Njormeld. He will use the pieces of that sacred relic in the construction of a mighty monument.\n\nMay it soothe the pains and heal the scars my people have borne these many years.\n\nMay its presence help to bring about a new age that sees us once again in glorious battle at Thorim's side.\n\nGo now, {class}. Njormeld awaits you.", sourceObjective = "King Jokkum wants you to bring Hodir's Horn Fragments to Njormeld in Dun Niffelem.", progress = "You have brought the fragments of Hodir's Horn, {race}?", completion = "<Njormeld's eyes become noticeably moist as he pours the contents of the bag onto the anvil.>\n\nThe Horn of Hodir....\n\nThis was a sacred gift to our people from Hodir himself, {race}. It is a relic of great importance to us.\n\nWhen you next return to our stronghold you shall see the fruits of your labor.\n\nFarewell.", sourceObjectiveStatus = "unverified-source-field" }
quests[12977] = { id = 12977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Call", description = "You have done a great service to the giants of Dun Niffelem. Without your aid, this monument would not exist.\n\nAs you silently ponder its significance, feelings begin to flood your heart. The feelings fill your mind with thoughts and images... as well as a sense of urgency.\n\nThe sensations fade and leave you with a knowledge of what you must do. The restless spirits at Thunderfall must be put to rest.\n\nAs you set off, you find that your hands have been filled with an ethereal horn.", sourceObjective = "You are to defeat 5 Niffelem Forefathers and 5 Restless Frostborn at Thunderfall. You are then to blow Hodir's Horn over their corpses, then return to Hodir's Horn in Dun Niffelem.", progress = "Strong gusts of wind swirl around the horn, causing its sound to echo throughout the surrounding mountains.\n\nTo any unknowing passersby, it might seem to be blowing itself....", completion = "You are filled with a sense of peace and contentment knowing that the once tormented souls of Thunderfall are now resting peacefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[12978] = { id = 12978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing the Storm", description = "Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken's betrayal, I turned my hammer toward our new foes.\n\nWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.\n\nYou've proven yourself a capable combatant and a staunch ally. Perhaps you'd be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.", sourceObjective = "Bruor Ironbane at Bouldercrag's Refuge wants you to kill 10 Nidavelir Stormforged. You may kill Stormforged Champions, Stormforged Magi, or Stormforged War Golems.", completion = "There may be hope for victory, {name}. We have never been able to sustain an attack on the stormforged, but with your efforts, Valduran may yet fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[12979] = { id = 12979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor of Darkness", description = "This armor plate is thick and oversized compared to the rest of the golem's defenses. A quick examination of the golem's corpse reveals that this heavier plate seems to have been bolted on as an afterthought or a crude upgrade.\n\nWhy would the iron dwarves have added this redundant and mismatched armor to their war golems?\n\nPerhaps Bruor Ironbane would know if he had the chance to examine several of these plates from stormforged war golems.", sourceObjective = "Bring 4 Dark Armor Samples to Bruor Ironbane at Bouldercrag's Refuge.", progress = "What is it you have there?", completion = "Careful, now. Keep that plate as far away from me as you can. Even being in its presence is enough to inflict pain.\n\nBut you're right, {name}, these are gigantic armor plates for a war golem of normal size. What would the stormforged be doing with them? There's only one way to find out.", sourceObjectiveStatus = "unverified-source-field" }
quests[12980] = { id = 12980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Armor's Secrets", description = "The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes.\n\nHe's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal.\n\nTo the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.", sourceObjective = "Take the Dark Armor Plate to Mimir's Workshop and ask Attendant Tock to examine it. When you're finished, return to Bruor Ironbane at Bouldercrag's Refuge.", progress = "What did you learn?", completion = "<Bruor listens as you describe what you learned in the workshop.>\n\nSo Valduran's master has given him this sinister metal to construct a giant weapon? That must be what he intends to use for the final strike against us! We need to stop him before he's able to complete it and unleash this weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12981] = { id = 12981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot and Cold", description = "As you stare at the anvil you relive your recent accomplishments, particularly those which brought this artifact to rest here.\n\nIt suddenly occurs to you that more remains to be done. To the east, smoldering scraps clutter the landscape--shrapnel from the battle fought there.\n\nIf they could be cooled and gathered somehow, the frost giants would have an abundant supply of metal and the region would be cleared of these remnants of war.", sourceObjective = "You are to go to Frostfield Lake, kill the Brittle Revenants there and use the Essence of Ice on the Smoldering Scraps at Fjorn's Anvil. You are then to collect 6 of the Frozen Iron scraps and return to Fjorn's Anvil in Dun Niffelem.", progress = "A luminous blue glow surrounds the anvil.", completion = "You feel a sense of accomplishment as you realize that your efforts continue to strengthen the renewed bonds between Thorim and the Sons of Hodir.", sourceObjectiveStatus = "unverified-source-field" }
quests[12982] = { id = 12982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ebon Blade Prisoners", description = "Now that I'm back, I'm certain that the baron will want me to recover my men. I can see that we're barely hanging on here. The Lich King's forces are about to break through and we won't be able to hold without my captured death knights.\n\nCan you assist me once more, {name}?\n\nGo back to Jotunheim and let them out of those cages. Break the damn locks, I don't care what you have to do. The vrykul likely have the keys.\n\nJust get my men free!", sourceObjective = "Vaelen the Flayed at The Shadow Vault wants you to free 8 Ebon Blade Prisoners. They can be found in the cages throughout the greater Jotunheim region.", completion = "Thank you, {class}. With the death knights that you freed, we'll be able to hold the line... for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12983] = { id = 12983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last of Her Kind", description = "For as long as I can remember, we've obtained our best bears from the Hibernal Cave to the east.\n\nThose times might finally be gone.  The cave has been overrun by ravenous jormungar and the wild bears are all but extinct.\n\nIf you were to find a surviving matriarch, however, I would guarantee you that she would fight better than any of these bears born in captivity.\n\nTake this harness to the Hibernal Cave and rescue a surviving matriarch.  Good luck finding one.", sourceObjective = "Astrid Bjornrittar in Brunnhildar Village wants you to rescue an Icemaw Matriarch in the Hibernal Cavern.", progress = "Did you find a matriarch?", completion = "I'm impressed.  I never thought I would see an icemaw matriarch again.  Especially not one this size.", sourceObjectiveStatus = "unverified-source-field" }
quests[12984] = { id = 12984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valduran the Stormborn", description = "We have no choice, {name}. What you learned in Mimir's Workshop means that we must act before Valduran can complete and unleash his new weapon.\n\nEven now, the refuge's defenders fight to buy us time to deal with Valduran the Stormborn.\n\nYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.", sourceObjective = "Use Bouldercrag's War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Valduran must be dealt with before the refuge falls.", completion = "At last, Valduran is dead, and the stormforged are weakened, but if his boasting is true, we must continue fighting the stormforged in his absence. This weapon they're building could be the end of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12985] = { id = 12985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging a Head", description = "Greetings, {race}.\n\nI have a task that King Jokkum felt you would be suited for, assuming you still strive to gain favor with our people.\n\nI have developed plans for another artifact, one that will grant Hodir's blessing of protection to our stronghold. I have nearly all that I require for its construction. All that remains to collect are the very eyes of our fallen enemies.\n\nTake this tool, and gather the eyes from the iron giant corpses that litter our fields.", sourceObjective = "Njormeld in Dun Niffelem needs you to use the Diamond Tipped Pick on the Dead Iron Giants at Frostfield Lake and return to him when you have collected 8 Stormforged Eyes.", progress = "Have you collected the final components I seek, {race}?", completion = "It is nearly done.\n\nWith this artifact in place, Dun Niffelem shall be warned of impending dangers before they are upon us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12986] = { id = 12986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Titans", description = "Norgannon's Core is not at this location. I am not sure why you seek it, {race}, and I am equally unsure if you truly know the purpose of that which you seek.\n\nI would like you to aid me before I consider extending my assistance.  I have recently encountered knowledge of the watcher, Thorim. His seat of power is contested, and his fate remains to be seen. This troubles me, for I do not know of the other watchers. Utilize this databank to examine their temples to the northeast and return the knowledge to me.", sourceObjective = "Creteus in the Foot Steppes has requested that you travel to the Temple of Invention, the Temple of Winter, the Temple of Life, and the Temple of Order and utilize the databank to examine each area.", progress = "Have you returned with the knowledge that I seek, {race}?", completion = "The news you bear forth is grave indeed. I do not know the fate of the remaining watchers, but their absence spells dark times for all of the lands of Azeroth.\n\nI shall examine the knowledge contained in the databank that you have returned and attempt to fully assess the situation. I believe I am in possession of knowledge that you deem more pertinent at this moment however, so I shall allow you to partake in said wisdom first.", sourceObjectiveStatus = "unverified-source-field" }
quests[12987] = { id = 12987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placing Hodir's Helm", description = "The helm is forged.\n\nYour efforts have not gone unnoticed, small one. Though there remains much to do, we sons of Hodir are grateful for your accomplishments.\n\nIn return, I offer you the opportunity to present Hodir's helm to our king and our brethren.\n\nFly to the sparkling tip of the small ice spike in front of me and read to our people from this tablet.\n\nEnjoy the privilege, {class}. Never before has an outsider been given such an honor!", sourceObjective = "Njormeld wants you to fly to the tip of the northern ice spike in Dun Niffelem and use the Tablets of Pronouncement.", progress = "Have you placed Hodir's Helm, {race}?", completion = "<Njormeld gazes up at Hodir's Helm, visibly moved.>\n\nThat will do, little {race}.\n\nThat will do....", sourceObjectiveStatus = "unverified-source-field" }
quests[12988] = { id = 12988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Forges!", description = "In my folly, I'd thought Valduran's project at Narvir's Cradle, a large construction area to the south, no more than a grotesque monument to \"Keeper\" Loken's cruelty.\n\nNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, {name}, for it will mean the end of the refuge.\n\nGo to Narvir's Cradle, find the lightning forges the stormforged artisans use, and sabotage them.", sourceObjective = "Destroy the North Lightning Forge, the Central Lightning Forge, and the South Lightning Forge with Bouldercrag's Bombs, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Were you able to hamper them by sabotaging the forges?", completion = "Excellent work! Oh, it won't stop the iron dwarves, but it'll take them valuable time to rebuild those forges. I daresay we've gained the advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[12989] = { id = 12989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slithering Darkness", description = "The vile jormungar have taken over most of the Hibernal Cavern.  They are despicable beings... children of Loken, Thorim's scumsucker of a brother.\n\nAs Thorim's servants we owe it to ourselves to kill these scum where we find them.  You'll find the cavern just east of here, outside the village.", sourceObjective = "Astrid Bjornrittar wants you to slay 8 Ravenous Jormungar in the Hibernal Cavern east of Brunnhildar Village.", completion = "The jormungar are vile creatures.  You did well in destroying them.", sourceObjectiveStatus = "unverified-source-field" }
quests[12990] = { id = 12990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wormhole", description = "Bring me materials and I'll teach you how to use your Wormhole Generator.You will learn:", sourceObjective = "Bring Jon LeCraft the materials he seeks to avoid a swift death, and to get a cool new spell.", sourceObjectiveStatus = "unverified-source-field" }
quests[12991] = { id = 12991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hit Them Where it Hurts", description = "Bouldercrag's got a good plan to stymie the efforts of the iron dwarves at Narvir's Cradle, and I've got an idea of my own. Work on the iron colossus will come to a halt without any artisans.\n\nNarvir's Cradle is on the south side of the hill sheltering Bouldercrag's Refuge. Go there and slay any stormforged artificers in your path. They may be no different from what we once were, but they build a weapon that threatens us all.", sourceObjective = "Kill 10 Stormforged Artificers and return to Bruor Ironbane at Bouldercrag's Refuge.", completion = "There were days when I could never ask someone to do what you did, but my experience with the iron dwarves has extinguished those feelings. We have bought time against the enemy's advance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12992] = { id = 12992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush Dem Vrykuls!", description = "Dem vrykuls at the Jotunheim needs to be crushed!\n\n{name} crush dems good!", sourceObjective = "Vile at The Shadow Vault wants you to slay any 15 vrykul in the greater Jotunheim region.", completion = "{name} is my bestest little {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12993] = { id = 12993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Colossal Threat", description = "You've done an excellent job of delaying the work on the iron colossus, but I fear we've only made the stormforged more determined to complete the weapon.\n\nEven now, they're bringing in new laborers and the overseers push them to the limit. We may not be able to keep them from bringing the colossus online, after all. Return to Narvir's Cradle, to the south and find the documents detailing the colossus' offensive and defensive abilities. They should be near the tents and forges on the bottom level.", sourceObjective = "Retrieve the Colossus Attack Specs and Colossus Defense Specs and bring them to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Did you find the documents we're looking for?", completion = "<Bouldercrag begins to look over the documents, his eyes wide.>\n\nI had no idea the irons were capable of this! Our men will have no chance against this behemoth if it's completed. Fortunately, it looks like they're still lacking a key part.", sourceObjectiveStatus = "unverified-source-field" }
quests[12994] = { id = 12994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy Hunter", description = "The rapport you've developed with the inhabitants of Dun Niffelem has yielded some unexpected discoveries.\n\nFor example, you somehow find yourself able to understand the denmother's guttural growls and sharp quips--at least you think you do.\n\nIt would seem that she senses danger outside the stronghold and wants you to do something about it.\n\nWith her forepaw, she removes the chain from around her neck and lets it drop at your feet. As you pick it up you notice an aged fang attached to it...", sourceObjective = "You must defeat 3 Stormforged Spies in the Valley of Ancient Winters.\n\nUsing the Ethereal Worg's Fang at the Corpse of the Fallen Worg will summon an Ethereal Frostworg, which will expose hidden enemies. You are to return to the Frostworg Denmother in Dun Niffelem when the valley has been cleansed of spies.", progress = "The frostworg denmother looks at you curiously.", completion = "As you slide the chain back around the denmother's neck she licks your face approvingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[12995] = { id = 12995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Our Mark", description = "We must attack the vrykul of Jotunheim on many levels. Brute force, of course, is good, but I prefer a more cerebral approach.\n\nI want you to demoralize them.\n\nMy men here have forged a number of banners for you. I would like for you to take and plant them near the corpses of fallen vrykul.\n\nLet the banners serve as a constant reminder to them that they face a more immediate threat than the wrath of the Lich King.", sourceObjective = "Baron Sliver at The Shadow Vault wishes you to plant 15 Ebon Blade Banners near the corpses of vrykul found within the greater Jotunheim region.", progress = "Oh now, {name}, I don't think you're quite done yet.", completion = "Well done, {name}. Let them see the desecrated corpses of their fallen comrades and think twice about striking at us!\n\nIf you come back tomorrow, I will make certain to have more banners prepared for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12996] = { id = 12996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warm-Up", description = "You've been very fortunate, sister.  This is a matriarch the likes of which hasn't been seen in years.\n\nA good bear won't do you much good without the skill to ride it.\n\nI'm going to have you practice some moves on Kirgaraak.  He's the largest yeti we've ever managed to capture so be careful.  Don't be afraid to walk away if he gives you a beating... there's a reason why we keep him chained.", sourceObjective = "Astrid Bjornrittar in Brunnhildar Village wants you to use the Reins of the Warbear Matriarch to defeat Kirgaraak.", progress = "How did it go with the yeti?", completion = "Not bad.  I was hoping Kirgaraak would snap your neck so I could keep your bear.\n\nJust joking, sister.  Well... half-joking.  That's a really nice bear you've got.", sourceObjectiveStatus = "unverified-source-field" }
quests[12997] = { id = 12997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Pit", description = "Besting a tethered opponent is one thing.  Fighting other bear riders on equal footing is another.\n\nHead into the Pit of the Fang and use what you've learned to defeat your opponents.  Good luck, sister.\n\nGlory awaits, should you succeed.", sourceObjective = "Astrid Bjornrittar, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", completion = "You really did it!  You made it out with your health.  Wish we could say the same for your bear.\n\nIt's going to take a while for her to recover.  Fortunately you won't need her for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[12998] = { id = 12998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Storm", description = "According to the documents you captured at Narvir's Cradle, the iron colossus is complete except for one key component -- the Heart of the Storm.\n\nWithout it, the iron colossus' weapons would be much weaker than the design predicts. If we can deny Overseer Narvir the heart, we could defeat the colossus!\n\nNotes on the documents you found say that the heart is in Uldis, a titan facility far to the south. Its entrance is on the south side of a tall mountain overlooking the Bor's Breath River.", sourceObjective = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to travel to Uldis and try to prevent Overseer Narvir from obtaining the Heart of the Storm.", completion = "With the heart in the hands of Narvir, the colossus will achieve its full power! We'll have no choice but to fight it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12999] = { id = 12999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bone Witch", description = "You remember Lady Nightswood, don't you? She certainly remembers you. She's the forlorn and very angry banshee that you 'saved' when you also broke Vile and myself out from under the Lich King's dominion.\n\nThe lady has gone into Jotunheim and possessed their bone witch. She intends to wreak havoc upon the vrykul from within.\n\nShe has asked that you seek her out. You'll find her in the cave on the south side of Njorndar Village to the southwest within Jotunheim.", sourceObjective = "Speak with The Bone Witch within the cave at Njorndar Village.", completion = "{name}, you came.\n\nAlready I have heard of your activities on the Savage Ledge. This is good. I am glad that you seem willing to help with undermining the vrykul here at Jotunheim.\n\n\n\nYou and I are going to have a great deal of fun with them!", sourceObjectiveStatus = "unverified-source-field" }
quests[13000] = { id = 13000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Measures", description = "The cold in these mountains is brutal.  We have a day or two before we burn up all the wood from the wreckage.\n\nWe spotted worgs inside a cave directly east of here.  I need you to find the cave and obtain some furs.  It might not sound like much, but it might be the difference between freezing to death and living another day.\n\nWorgs don't hunt alone, so I'm giving you a flare.  It should buy you some time if you find yourself outnumbered.", sourceObjective = "Bloodguard Lorga wants you to go to the Gimorak's Den to the east and obtain 6 Worg Furs.", progress = "Did you bring the furs?", completion = "These furs are rather... large.  I'd hate to see the worgs you had to face off with.\n\nWe're all very thankful.  The temperature is starting to drop already.", sourceObjectiveStatus = "unverified-source-field" }
quests[13001] = { id = 13001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging Hodir's Spear", description = "The time has come, little {class}. The stars have foretold of this day.\n\nI have received a vision from mighty Hodir himself, revealing the secret to the creation of a great artifact.\n\nWe must obey! Were we to fail in receiving this gift, doom would surely follow.\n\nI call upon you to assist me in this sacred undertaking.\n\nGo across the valley, deep into the Hibernal Cavern and gather everfrost shards from the icy crater there, then collect hides from the mammoths outside the cavern.", sourceObjective = "Lorekeeper Randvir in Dun Niffelem wants you to collect 3 Everfrost Shards from the depths of Hibernal Cavern and 3 Stoic Mammoth Hides from the Stoic Mammoths in the Valley of Ancient Winters.", progress = "Have you gathered the materials for the spear, {race}?", completion = "Stand back, {race}, and behold the fulfilling of a prophecy!", sourceObjectiveStatus = "unverified-source-field" }
quests[13002] = { id = 13002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "Welcome to de cold, mon.  Dis place may not be so good for keepin' me bones warm, but I have learned how to cut me de perfect gem.  All I be needin' is some gems to do me work on.\n\nBring me some gems and I be teachin' you the skill of gem perfection.  Dis will allow you to sometimes cut a perfect gem with increased bonuses when cuttin' an uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Geba'li in Warsong Hold.", progress = "Dis is what I been lookin' for.   Now I be learnin' you Gem Perfection.", completion = "Dey be perfect mon'.    Here is the art of gemcutting perfection for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[13003] = { id = 13003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How To Slay Your Dragon", description = "Hodir's Spear is an icon of great prowess in battle.\n\nIts mere presence instills a deep hunger for glory in all who enter Dun Niffelem. In fact, simply being near it has compelled you to test your own abilities.\n\nScanning the horizon, your vision locks on a wild wyrm as it flies nearby.\n\nIt is decided. Of you and he, only one shall see the next sunrise....", sourceObjective = "You are to use Hodir's Spear to challenge a Wild Wyrm in the Valley of Ancient Winters. Once in its grip, you are to fight to the death.", completion = "It is done.\n\nYou have stared certain death in the face and emerged victorious.\n\nBy single-handedly defeating such a mighty beast, you have brought great honor to Dun Niffelem!", sourceObjectiveStatus = "unverified-source-field" }
quests[13004] = { id = 13004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "There's a war going on and we each must do our part!  Mine is cutting gems and not only can I cut normal gems but I have the skill to cut perfect gems as well.   If you can bring me several uncut gems to contribute to the cause, I can teach you gem perfection as well.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Alestros in Valiance Keep.", progress = "Your donation is much appreciated.   Let me teach you of gem perfection.", completion = "Thank you.   I shall teach you of gemcutting perfection and in addition give you a perfect gem that I have cut.", sourceObjectiveStatus = "unverified-source-field" }
quests[13005] = { id = 13005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen Oath", description = "For years I neglected my duties, giving into defeat and self-pity.\n\nNot the brave earthen, however.  Their oath to protect these grounds with their lives has gone unbroken.\n\nEven now, they fight the corruption of iron with selflessness, waiting for the moment in which the tides turn.\n\nThat moment has arrived.  We must rally what remains of the earthen defenders and lead them into a glorious victory.  Sound the Horn of the Peaks to call them to your side and take back the Terrace of the Makers.", sourceObjective = "Thorim, at the Terrace of the Makers, wants you to use the Horn of the Peaks and call on the Earthen to defeat 20 Iron Dwarves and 7 Iron Sentinels.", progress = "Hail, {name}!  What news do you bring?", completion = "It's a good start.  But my brother's forces will not take long to regroup.  We must make our victory a decisive one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13006] = { id = 13006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Viscous Cleaning", description = "As you draw near the helm, you notice that the frigid environment is already taking its toll on the artifact's surface. What is now just a thin layer of ice will surely grow to envelop it entirely.\n\nNot about to let your hard efforts go to waste, you resolve to scour the region in search of a solution.\n\nJust as you set off, the eyes of the helm flash and an image of the nearby Hibernal Cavern enters your mind.", sourceObjective = "You are to enter Hibernal Cavern west of Dun Niffelem and collect 5 units of Viscous Oil from the Viscous Oils there.\n\nYou are then to return to Dun Niffelem and apply the oil to Hodir's Helm.", progress = "Frost is thickening on the helm as you watch, and icicles are beginning to form around its edges...", completion = "As you coat the helm with a thin layer of oil, the frost falls away and the surface gleams.", sourceObjectiveStatus = "unverified-source-field" }
quests[13007] = { id = 13007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Colossus", description = "We have failed to prevent the completion of the iron colossus, {name}, which means we have no choice but to face it in battle.\n\nBruor has devised a plan to exploit the colossus' only weakness.\n\nNo matter how tough the colossus' armor is, it is still vulnerable to a jormungar's acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the iron colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.", sourceObjective = "Use a Tamed Jormungar to defeat the Iron Colossus and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Have you defeated the iron colossus and spared the refuge from destruction?", completion = "We've done it, we've really done it! The refuge is spared and the stormforged are defeated! We must warn Brann before Loken gets it in his mind to try to rebuild his forces. The only way to secure the victory you have won today is to go into Ulduar and defeat Loken for all time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13008] = { id = 13008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge Tactics", description = "We had the element of surprise on our side! We blew a hole in the side of the mountain and charged into Scourgeholme. Scourge opposition was fierce and it wasn't long until we were overwhelmed. We fell back to the valley and began raining artillery down on the Scourge that followed. This held them back for awhile until... Those monsters began using crusaders as living shields. We had to stop shelling for fear of killing our own soldiers.\n\nFree our crusaders trapped on the field outside the base, {class}!", sourceObjective = "Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 8 Webbed Crusaders.", completion = "There are still many Argent Crusade soldiers out on that field and in Scourgeholme, {name}. While your help is appreciated, there is still much left to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13009] = { id = 13009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "It remains uncertain whether or not our people can ever rekindle the affection we once held for Thorim.\n\nMay this armor, if nothing else, remind him of the days when we stood together in honor, invincible.", sourceObjective = "Njormeld wants you to take the Reforged Armor to Thorim at the Temple of Storms.", progress = "How have your efforts fared, {class}?", completion = "<As you present Thorim with the reforged suit of armor, he is visibly stricken by its splendor.>\n\nYou have done well, {race}, but there remains much to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13010] = { id = 13010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krolmir, Hammer of Storms", description = "One task remains before I can reclaim my home at the Terrace of the Makers.\n\nKrolmir must be found.\n\nOn that fateful day, I threw it to the earth with all the power and rage I possessed. A mighty explosion followed.\n\nI've thought it lost for these many years, but now I must be certain.\n\nReturn to King Jokkum and discover what, if anything, he knows of my hammer's fate.", sourceObjective = "Thorim wants you to talk to King Jokkum in Dun Niffelem and discover what he knows of Krolmir.", progress = "Back again, little {race}?", completion = "Words cannot express my gratitude, {class}.\n\nYou have served me honorably. Please accept this token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[13011] = { id = 13011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling Jorcuttar", description = "I have an opportunity that will help you to gain approval with my people, provided you prevail.\n\nThe jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire.\n\nThey have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region.\n\nShe cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.", sourceObjective = "King Jokkum in Dun Niffelem wants you to slay Jorcuttar in Hibernal Cavern.", progress = "Have you slain Jorcuttar?", completion = "So it is done.\n\nWe have heard the screams of Jorcuttar as they echoed from across the valley.\n\nYou have done our people a service this day, little {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13012] = { id = 13012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sardis the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
