quests[13033] = { id = 13033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arp the Elder", sourceObjective = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13034] = { id = 13034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witness and the Hero", description = "When I began my travels in Northrend, I visited the Borean Tundra and met the taunka for the first time. There, Wind Tamer Barah told me the tale of Stormhoof and his battle against the North Wind, their people's ancient enemy.\n\nI set out for the Storm Peaks to learn more of this hero, but strangely, the people of Tunka'lo seem to know nothing of him.\n\nPerhaps the camp's own records will give us greater insight. Find and read the history scrolls kept throughout the camp, then tell me what you learned.", sourceObjective = "Xarantaur, at Camp Tunka'lo, wants you to read the First History Scroll, the Second History Scroll, and the Third History Scroll.", progress = "What have you learned from the records of Camp Tunka'lo?", completion = "How peculiar... that doesn't sound like the story Wind Tamer Barah told me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13035] = { id = 13035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loken's Lackeys", description = "The attack on the Terrace of the Makers was not a half-hearted move on my brother's behalf.  He sent a legion of iron dwarves and some of his most powerful lieutenants.\n\nUse the Horn of the Peaks to call the earthen to your side and defeat Loken's servants.\n\nYou'll find the giant, Eisenfaust, inside the Hall of the Shaper to the north.  You'll find the others deeper inside the Terrace of the Makers, beyond the stairs to the northwest.", sourceObjective = "Thorim wants you to slay Eisenfaust inside the Hall of the Shaper and Halefnir the Windborn and Duronn the Runeforged in the Terrace of the Makers.", progress = "It's good to see you again, {name}.", completion = "One by one, my brother's servants have fallen.  Loken's insurrection will soon come to an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[13036] = { id = 13036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Above All Else", description = "Long has been the path to our salvation, young {class}. We have fought across continents, worlds even, to reach this point. Now we face our greatest challenge: the destruction of the Lich King and his Scourge.\n\nAlas, we fight this battle divided. The Horde and Alliance are in the throes of war and will lend us no support. We must remain unyielding in our cause! For what choice have we to do otherwise?\n\nDo you join the cause? Lend us your strength, {class}! My commander, Entari, awaits you at his post.", sourceObjective = "Report to Crusade Commander Entari at the Argent Vanguard in Icecrown.", completion = "Where both the Alliance and the Horde failed, the Argent Crusade succeeded. The success, however, was short lived. Our breach into Icecrown was quickly - and with force - rebuffed.\n\nThe Lich King's retaliatory strike was immediate and brutal. Now we are on the defensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[13037] = { id = 13037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of Stormhoof", description = "When the bronze dragonflight gifted me with immortality and set me on the path of the witness, Nozdormu entrusted me with the Lorehammer.\n\nThe hammer's reaction to your findings means that time has gone awry here and it is our duty to restore the true timeline.\n\nWe must find it. To the northwest is Frostfloe Deep, ancient burial cave of the warriors of Tunka'lo. Seek out the spirit of Chieftain Swiftspear, Stormhoof's brother. Ask him what he remembers of his brother's battle against the North Wind.", sourceObjective = "Speak with Chieftain Swiftspear in Frostfloe Deep, then return to Xarantaur at Camp Tunka'lo.", progress = "What have you learned from spirit of Chieftain Swiftspear?", completion = "Even the chieftain is beginning to lose his memories? The past is being rewritten before our eyes and if we do not find out who is behind this, the entire legacy of Stormhoof could be lost forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[13038] = { id = 13038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distortions in Time", description = "This, the tomb of Tunka'lo's warriors, is supposed to be a serene place, free from the terror of the elements.\n\nFrostfloe Deep has been invaded by a strange force, one that disturbs the spirits of the fallen and blurs my memories of my own life.\n\nIt's as though our deeds and memories are being erased from history.\n\nIn life, this totem was a symbol of my authority. It is the last true link I have to this world. Take it, use it to restore calm to the tomb, and then return it to Camp Tunka'lo.", sourceObjective = "Use the Chieftain's Totem to close 4 Frostfloe Rifts, then bring the totem to Xarantaur at Camp Tunka'lo.", progress = "What is it you have brought from the tomb?", completion = "The chieftain's spirit told you to bring this to me?\n\n<Xarantaur examines the totem.>\n\nAh, I see what he intended. By telling you to use this totem to close the rifts in the deep, he has given us a clue as to what's happening to the timeline. A wise chieftain, this Swiftspear, watching over his people even in death.", sourceObjectiveStatus = "unverified-source-field" }
quests[13039] = { id = 13039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending The Vanguard", description = "We can't keep this pace up, <lad/lass>. Once the breach was blown, the floodgates opened up. The Scourge have been pourin' through ever since with no end in sight!\n\nWe need every able bodied man and woman to help keep the tide of evil at bay. Get out there and do yer share, friend. Kill as many of those monsters as ye can!", sourceObjective = "Crusader Lord Dalfors at the Argent Vanguard in Icecrown has asked that you kill 15 Forgotten Depths Nerubians.", progress = "Don't give up, {name}!", completion = "How many of them could there possibly be? We've killed enough to fill ten graveyards and still they come. The situation looks grim, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[13040] = { id = 13040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curing The Incurable", description = "The number of injured soldiers rises with each passing day. They are being stricken by some type of toxin that we have never before seen. Whatever it is that these Nerubians hold within their venom glands is lethal and incurable! So far we've only been able to slow down the poison flowing through the victim's bodies. We must devise a cure!\n\nVenture northwest to the valley outside of the Vanguard and slay the Forgotten Depths Nerubians. Recover their venom glands and bring them to me.", sourceObjective = "Father Gustav at the Argent Vanguard in Icecrown has asked that you bring him 10 Forgotten Depths Venom Sacs.", progress = "Have you recovered the venom glands, {race}?", completion = "Thank you, {name}. I will begin the tests on these samples immediately. It is my hope that a cure will be found soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[13041] = { id = 13041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish the Shipment", description = "I'm glad you showed up!   A shipment of Glowing Ivory Figurines needs to go out to Undermine right now, and I am still short a Chalcedony to complete an eye for the last one.\n\nBring me one and a Dalaran Jeweler's token will be yours.", sourceObjective = "Bring a Chalcedony to Timothy Jones in Dalaran.", progress = "Do you have the Chalcedony yet?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  I have new shipments going out all the time, check by from time to time to see what I need.", sourceObjectiveStatus = "unverified-source-field" }
quests[13042] = { id = 13042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep in the Bowels of The Underhalls", description = "Deep in the bowels of The Underhalls to the northeast, a mad scientist known as Dr. Terrible is up to something befitting his name.\n\nThe doctor has been given dispensation by the Lich King to perform experiments upon the vargul -- the vrykul who fall in battle and are found unworthy, and then turned into Scourge.\n\nWe must put an end to his work, but my auguries have been unable to find him. He does, however, have an assistant.\n\nBeat the information out of his apprentice, and then dispose of the body.", sourceObjective = "The Bone Witch in Njorndar Village has asked you to beat information out of Apprentice Osterkilgr concerning what Dr. Terrible is truly up to.\n\nYou are then to slay the apprentice.", progress = "You have not finished what I asked of you.\n\nPlease leave and do not return until you have done so or I will be very cross.", completion = "Very interesting. It sounds to me that you handled that perfectly. I'm surprised that the doctor was using a vargul as an assistant given what he was working on.", sourceObjectiveStatus = "unverified-source-field" }
quests[13043] = { id = 13043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sum is Greater than the Parts", description = "Opening the tome, you notice all manner of disgusting illustrations concerning the construction of what the doctor refers to as \"the ultimate weapon\"!\n\nClearly the prototype, Nergeld, is the massive flesh giant standing still at the end of the nearby Hall of Horrors.\n\nIf an army of those things were to be constructed, then it would mean doom. The only way to ensure that doesn't happen is to slay Dr. Terrible!\n\nPerhaps if you were to take control of the construct, the doctor would reveal himself?", sourceObjective = "Mount and take control of Nergeld. Defend it from the denizens of the Hall of Horrors until Dr. Terrible shows himself.\n\nUse Nergeld to slay the doctor, and then return to The Bone Witch in Njorndar Village.", progress = "You recovered the doctor's tome, but you didn't finish him off using the flesh giant?\n\nGet back in there and kill him before it's too late!", completion = "You discovered and put an end to the doctor's machinations.\n\n<The banshee-controlled witch smiles and places a large hand gently upon your shoulder.>\n\nThat's a fine poke in the eye for the Lich King, but I think we can do better.", sourceObjectiveStatus = "unverified-source-field" }
quests[13044] = { id = 13044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If There Are Survivors...", description = "Across the Valley of Echoes, west of here, and through the Breach, is the first Scourge encampment in Icecrown known as Scourgeholme. We fought a good fight at Scourgeholme and killed many Scourge, but in the end we were forced to retreat. Many soldiers were left behind - their fate unknown.\n\nIf there are survivors, we must attempt a rescue. Directly down this southeastern path is Penumbrius, ally of the bronze dragonflight and caretaker of the proto-brood. Seek him out and ask for his assistance.", sourceObjective = "Speak with Penumbrius at the Argent Vanguard in Icecrown.", completion = "<Penumbrius nods.>\n\nMy kin will help. Together we will battle the Lich King and his undead legions.", sourceObjectiveStatus = "unverified-source-field" }
quests[13045] = { id = 13045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Wild Green Yonder", description = "We will do all that we can to assist you, {name}. The proto-brood have volunteered to fly you across the Breach and into Scourgeholme. Rescue any captured Argent Crusaders that you find. Return them immediately to the Vanguard Infirmary, located at the center of this base.\n\nChoose one of the Argent Skytalons in the pen behind me and go!\n\nScourgeholme is located northwest, across the Valley of Echoes, through the great Breach.", sourceObjective = "Rescue 3 Captured Argent Crusaders from Scourgeholme and drop them off at the Vanguard Infirmary at the center of the Argent Vanguard. Report to Highlord Tirion Fordring should you succeed.", progress = "With each minute that passes their chance of survival decreases.", completion = "Arthas... He strikes recklessly - without care or caution. We have caught him off guard.\n\n<Highlord Tirion Fordring pauses, lost in thought for a moment.>\n\nWe will bolster our defenses and weather the storm.\n\nHow good are you with a cannon, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13046] = { id = 13046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Arngrim", description = "Arngrim's hunger was legendary.\n\nEven in death, his expression is one of famished yearning. You find that just looking at him is making your stomach growl.\n\nIt is said that throughout his life he was never truly sated, and that there was absolutely nothing he wouldn't eat. You wonder to yourself if there might be a way to feed the old king.\n\nNo sooner does the thought enter your mind than one of the massive frozen teeth falls from Arngrim's head, bounces off of his beard and lands in your hand.", sourceObjective = "You are to feed Arngrim 5 Disembodied Jormungar, then return to Arngrim's frozen image in Dun Niffelem.\n\nYou must go to the Valley of Ancient Winters and use Arngrim's Tooth on the Roaming Jormungar there. Once they have become disembodied, you must fight them until they are weakened.", completion = "As you anchor the tooth in Arngrim's jaw, you get the impression that your efforts may have taken the edge off of the old king's hunger pangs... for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13047] = { id = 13047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reckoning", description = "Loken killed my wife, turned my followers and me against each other.  He took away everything I had, but today... that changes.\n\nToday we reclaim our sacred grounds.  Today... Loken dies.\n\nMeet me on the bridge near the Temple of Wisdom, just southwest of Ulduar.  I will finish this one way or the other.\n\nI need you there as a witness.  You will not aid me -- this is personal.\n\nAfter it's done, send word to Jokkum, King of the Frost Giants.  He's a good friend and will know what to do.", sourceObjective = "Meet Thorim near the Temple of Wisdom. Report the outcome of the fight to King Jokkum in Dun Niffelem.", completion = "No... it cannot be...\n\nNo one can defeat Thorim in single combat.  Not a giant, nor a beast... no one!  Especially not that coward of a brother of his.\n\nOn my forefathers' names, this I swear...\n\nLoken will pay for this!", sourceObjectiveStatus = "unverified-source-field" }
quests[13048] = { id = 13048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Time Went Wrong", description = "The Lorehammer can help us correct the damage to the timeline, but only if we can discover where the history was originally corrupted.\n\nFrom Chieftain Swiftspear and your findings at Frostfloe Deep, we know that the change happened around the time of Stormhoof's death.\n\nNow, you must go to the Howling Hollow, north of the camp, and inspect the gravesites the North Wind's minions have already destroyed. The Lorehammer will react to artifacts from Stormhoof's era and attune itself to the proper time.", sourceObjective = "Use the Lorehammer on Taunka Relics to attune it to the time of Stormhoof. Once it has been attuned to 6 relics from the time of Stormhoof, return to Xarantaur at Camp Tunka'lo.", progress = "Have you attuned the Lorehammer to the time period of Stormhoof?", completion = "<Xarantaur accepts the Lorehammer from you.>\n\nAt last, we've pinpointed the time of Stormhoof in history. With this knowledge, we can restore the timeline.", sourceObjectiveStatus = "unverified-source-field" }
quests[13049] = { id = 13049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero's Arms", description = "Not all of the camp's records have yet been corrupted. My staff has helped me to find those records which reflect the true timeline.\n\nThey agree that Stormhoof was given a burial of honor among the village elders on the bottom level of the Howling Hollow, to the north.\n\nMost of the graves there have already been destroyed, their contents taken as trophies by the North Wind's subjects. Go to the hollow and see if you can recover Stormhoof's spear and armor from the scions of storm who have claimed them.", sourceObjective = "Recover Stormhoof's Spear and Stormhoof's Mail and return them to Xarantaur at Camp Tunka'lo.", progress = "Have you found Stormhoof's weapon and armor?", completion = "We are fortunate that you have recovered these intact, {name}. With them, I can use the Lorehammer to send you back in time, to where the North Wind started to corrupt the true timeline. It's the only way we can restore the true history of this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[13050] = { id = 13050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veranus", description = "If I'm to launch an attack against my brother's army, I'm going to need some way to get around.\n\nI released my riding drake back into the wild years ago.  Veranus was magnificent.  The leader of her own brood -- to whom she has now returned.\n\nFinding her will be hard, but perhaps there's a way.  She keeps her old empty nest out of pure pride.  She's a broodmother in name only, for she is beyond the age of breeding.\n\nBring me small eggs from the other nests near Brunnhildar.  I think I've an idea.", sourceObjective = "Thorim, at the Temple of Storms, wants you to obtain 5 Small Proto-Drake Eggs from the peaks near Brunnhildar Village.", progress = "Did you obtain the eggs, {name}?", completion = "Yes... these will do.  Let us hope my plan works, {name}.\n\nVeranus is a great drake.  I'd hate to have to settle for a lesser one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13051] = { id = 13051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territorial Trespass", description = "Veranus is proud like no other beast I've known.  She still keeps her old nest and makes sure none of the younger proto-drakes takes it over.\n\nTake the eggs you've collected and place them on her nest.  You'll find it atop a small peak, directly southeast of here.\n\nI should be able to get control of her before she kills you in a fit of rage.  Hopefully.", sourceObjective = "Place the Stolen Proto-Dragon Eggs on top of the Broodmother's Nest and return to Thorim at the Temple of Storms.", progress = "Hail, {name}!", completion = "It's good to have my old friend back.  It appears that my luck is finally starting to change... and it's all thanks to you, little friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[13052] = { id = 13052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Surveillance", description = "You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northwest.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.", sourceObjective = "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northwest. I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing. Tell Vic I sent you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13053] = { id = 13053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Survivors", description = "Gretchen Fizzlespark wants to use my flying machine to look for survivors from her expedition.  Apparently she thinks they're being held prisoner in the village to the north.\n\nThe only problem is I don't have a co-pilot.  If you're willing to take it on, I'd be more than happy to teach you a move or two.\n\nWhat do you say, {name}?  Deal?You will learn:", sourceObjective = "Help Zak Wobblesprocket complete the Test Flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[13054] = { id = 13054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Tracker", description = "I can't in good conscience send you to the worg cave without warning you that the previous person we sent there hasn't returned.\n\nWe're prepared for the worst, but perhaps there's a chance that he's alive.  We'd appreciate it if you helped him return -- Tracker Val'zij is one of the only hunters we have.", sourceObjective = "Look for Tracker Val'zij inside Gimorak's Den, southeast of the Grom'arsh Crash Site.", completion = "This hurts bad, mon.  Don't know if I'm gonna make it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13055] = { id = 13055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cave Medicine", description = "It's good to see a friendly face.  Might be the last one I see.\n\nOne of those jormungar stung me with some sort of toxin before I managed to get away.  I can feel my whole body getting numb, mon.\n\nI'm going to need a toxin gland to make an antidote.  I will also need some of the cave mushrooms that grow here... they'll slow the toxin down.\n\nHurry, please.  I don't have much time.", sourceObjective = "Tracker Val'zij, at Gimorak's Den, wants you to obtain 1 Jormungar Toxin Gland and 8 Cave Mushrooms.", progress = "You back, mon?", completion = "I thank you, mon.  I might live another day now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13056] = { id = 13056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Always Time for Revenge", description = "I should manage for now, {name}.  There is one favor I'd like to ask, though.\n\nI would never had fallen to one of these worms, but my wind serpent, Heesha, was killed by the meanest worg I've seen in some time.\n\nDon't worry about me now, I'll feel better when that worg is breathing no more.  You should find him deeper in the cave.", sourceObjective = "Tracker Val'zij wants you to slay Gimorak inside Gimorak's Den.", progress = "You find that dirty mongrel, {name}?", completion = "I'm already feeling much better, mon.  Not sure if it's the antidote or the news of that filthy worg getting what he deserved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13057] = { id = 13057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrace of the Makers", description = "It is time, {name}.  I am prepared to face Loken now.\n\nLet us make our way to the Terrace of the Makers and face my brother's forces.  The fool will regret ever crossing me.", sourceObjective = "Find Thorim at the southeastern edge of the Terrace of the Makers, just northwest of Dun Niffelem.", completion = "We're here, {name}.  My brother's forces will learn the meaning of defeat today.", sourceObjectiveStatus = "unverified-source-field" }
quests[13058] = { id = 13058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing the Wind's Course", description = "At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona.\n\nTake the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens.\n\nThen, you must find and use the Horn of Elemental Fury to destroy the North Wind.", sourceObjective = "Use the Lorehammer to travel back in time and face the North Wind as Stormhoof. When Stormhoof falls and drops the Horn of Elemental Fury, use it to finish off the North Wind, and then return to Xarantaur at Camp Tunka'lo.", progress = "Have you done it? Is the true timeline restored?", completion = "What you have done today will ensure that Stormhoof and his story will never be forgotten. As well, you have written yourself into the pages of Azeroth's history. I will remember and record your accomplishments for all eternity.", sourceObjectiveStatus = "unverified-source-field" }
quests[13059] = { id = 13059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge for the Vargul", description = "I've been praying to The Lady of the Sword for one to come and strike down my enemy. Thane Illskar must pay for what he did to me!\n\nI was the champion of Thane Ufrang the Mighty. During my fight for ascendance in Valhalas, Illskar sabotaged me with dark magic, causing me to lose and be reduced to this.\n\nThe thane and his champions can be found below in The Circle of Suffering. Challenge him on my behalf. Defeat him.\n\nMake him know the suffering that I know!", sourceObjective = "Bethod Feigr in The Underhalls wants you to throw down his sword to challenge Thane Illskar and then kill him in The Circle of Suffering.", progress = "I sense that you haven't yet defeated Thane Illskar. Does something stay your hand?", completion = "Thank you, {class}... thank you!\n\nYou've given me the satisfaction of knowing that the coward who made me into this will rot for all eternity as surely as I will.\n\nNow leave before I lose control of myself and cut you down.", sourceObjectiveStatus = "unverified-source-field" }
quests[13060] = { id = 13060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", sourceObjective = "Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks.", completion = "<Olut winces.>\n\nThat looked painful. It was a pretty grand entrance though.\n\nAre you here to help us find a path into Icecrown? As you can see, our first foray in that direction didn't end too admirably. I'm thinking we might be better off breaching the place from another side.", sourceObjectiveStatus = "unverified-source-field" }
quests[13061] = { id = 13061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Glory", description = "This is it then.  I'll take care of your bear now, you won't be needing her.  The great Drakkensryd will be your next challenge.\n\nSay goodbye to your friends and leave your affairs in order, for you will return victorious... or you won't return at all.", sourceObjective = "Speak to Lok'lira the Crone in Brunnhildar Village.", completion = "You've really made it this far.  Never would I have thought you'd progress so quickly among the hyldnir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13062] = { id = 13062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok'lira's Parting Gift", description = "You've been a great ally, {name}.  Now comes your true test.  You will need skill, courage and a little luck.\n\n<Lok'lira attaches a thin strand of hair to yours.>\n\nYou cannot fail now sister.  Speak to Gretta the Arbiter.  She'll see you on your way.", sourceObjective = "Speak to Gretta the Arbiter in Brunnhildar Village.", completion = "Are you ready to ride, sister?  There is no coming back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13063] = { id = 13063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deemed Worthy", description = "You have succeeded where many have failed, sister. Whether it be by strength and courage or mere luck remains to be seen.\n\nGo back to the village and seek out Astrid Bjornrittar. Tell her of your accomplishments. But be warned. She is not easily impressed.", sourceObjective = "Brijana wants you to go to Brunnhildar Village and speak with Astrid Bjornrittar.", completion = "So, sister, you think that completing a few simple chores makes you a heroine?\n\nYou shall learn....", sourceObjectiveStatus = "unverified-source-field" }
quests[13064] = { id = 13064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sibling Rivalry", description = "Sif? Is it truly you?\n\nNo? A {race}? But for a moment....\n\nEnough of this! The visions of my Sif have tormented me for far too long. It is time for me to avenge her, and to bring honor to her memory.\n\nMy brother must pay!", sourceObjective = "Thorim wants you to listen to his story.", progress = "Hear my words, {race}.", completion = "You now know a bit of the history of this land... my land.\n\nI call upon you to assist me in setting these wrongs to right.", sourceObjectiveStatus = "unverified-source-field" }
quests[13065] = { id = 13065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohanzee the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13066] = { id = 13066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yurauk the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13067] = { id = 13067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chogan'gada the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13068] = { id = 13068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Valor", description = "Perhaps you've heard the praises for our missing hero?\n\nCrusader Bridenbrad was in the Broken Front aiding the attack against the Scourge when the undead army came down upon them. The many men of that allied force scattered, but Bridenbrad alone returned and dragged more than a dozen men to safety, one by one through the carnage.\n\n{class}, he has not returned since. He was spotted heading to the far northeast, towards the Silent Vigil. Bring him back to me that I might honor him for his valor.", sourceObjective = "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you locate the hero, Crusader Bridenbrad at the Silent Vigil, in northeast Icecrown. His fire pit will likely be the most obvious indication of his location from the air.", completion = "Back! Careful! The plague has gripped me and I'll not see it spread to you nor anyone else.", sourceObjectiveStatus = "unverified-source-field" }
quests[13069] = { id = 13069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoot 'Em Up", description = "Jotunheim has aerial defenses, both in terms of proto-drake riders and harpoon guns. They've concentrated these on their northern and western facings where they are most vulnerable.\n\nLet's use their defenses against them!\n\n<The Leaper pierces you with his single eye and cackles maniacally.>\n\nTake control of a harpoon gun on the platforms that overhang the cliffs on either side of Valhalas to the southwest. Take out the proto-drakes and their riders. Shoot 'em up!", sourceObjective = "The Leaper at The Shadow Vault wants you to use a Jotunheim Rapid-Fire Harpoon to shoot down 15 Jotunheim Proto-Drakes and their riders.", completion = "You are a true champion for the cause, {name}!\n\nWon't you please come speak to me again tomorrow? I'm certain that there will be more of those nasty proto-drakes to shoot down.", sourceObjectiveStatus = "unverified-source-field" }
quests[13070] = { id = 13070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cold Front Approaches", description = "The chill of death stirs in the west, threatening to freeze our hearts and souls to this wasteland and bind us to its dark master. We will stand and we will fight!\n\nThe preparations have begun. Report to Siegemaster Fezzik at the front gate for your assignment.", sourceObjective = "Report to Siegemaster Fezzik at the Argent Vanguard in Icecrown.", completion = "We must be quick or face being overtaken by the Scourge! There's really no time for instructions, {race}. You're just going to have to jump in and hope for the best.", sourceObjectiveStatus = "unverified-source-field" }
quests[13071] = { id = 13071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Like Fire!", description = "Vile like fire! Vile like proto-drakes!\n\n<The abomination claps its hands excitedly.>\n\nLittle {name} go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!", sourceObjective = "Vile at The Shadow Vault wants you to steal a Njorndar Proto-Drake and use it to set fire to 8 vrykul buildings in the greater Jotunheim region.\n\nBalargarde Fortress, due to its nature, cannot be set ablaze.", progress = "What? Vile not see lots of fire!!!\n\n{name} go back and make more fire!", completion = "Yay, yay! {name} is best proto-drake stealer.\n\nYou come back tomorrow and we make more fire!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[13072] = { id = 13072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero Remains", description = "I know why you've come... they've sent you to bring me back, but that cannot happen. I carry the plague of undeath, {class}, and I'll not share my fate with those near me. No, I shall stay here.\n\nMy only regret lies in what I may become when death grips me. I do not fear death itself, but I loathe to consider serving the traitor, Arthas.\n\nLeave me... and see to it that no one else comes looking. You would do me a great disservice if you were to expose anyone to the plague that I carry.", sourceObjective = "Bring news of Crusader Bridenbrad's fate to Highlord Tirion Fordring at Crusaders' Pinnacle.", completion = "Bridenbrad has contracted the plague? I cannot imagine a worse fate for one who has devoted his life to the ways of light, nor can I fathom leaving him to die without lifting a finger to help.\n\nNo, undeath shall not be his fate. We shall find a way to aid this hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[13073] = { id = 13073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keeper's Favor", description = "There are those of this world that tap into power unrestricted by the bounds of our mortal frames - powers of restoration, powers of life, and powers of light.  And Bridenbrad, this is no ordinary man... his valor and devotion shine through. We can only hope that one of these beings will intervene and bring this hero back from a fate worse than death.\n\nGo now and speak to Arch Druid Lilliandra in the Argent Vanguard... request passage to Moonglade and seek the aid of Keeper Remulos.", sourceObjective = "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you secure passage from Arch Druid Lilliandra and speak to Keeper Remulos in Moonglade.", completion = "Hello child.\n\nI understand Tirion's request and trust in his judgment, we will see what we can do for this Crusader Bridenbrad. What you ask is no simple task - the Scourge are not of this world, and many have failed in attempting to strip their corruption over the years.\n\nIn a being of nobility and light, all is not without hope.", sourceObjectiveStatus = "unverified-source-field" }
